import { useEffect, useState } from 'react'

const load = () => {
  try { return JSON.parse(localStorage.getItem('todos')) ?? [] } catch { return [] }
}

export default function TodoApp() {
  const [todos, setTodos] = useState(load) // lazy init: read storage once
  const [text, setText] = useState('')
  const [filter, setFilter] = useState('all')
  const [editing, setEditing] = useState(null) // { id, text } or null

  useEffect(() => {
    localStorage.setItem('todos', JSON.stringify(todos))
  }, [todos])

  const add = () => {
    const t = text.trim()
    if (!t) return
    setTodos([...todos, { id: crypto.randomUUID(), text: t, done: false }])
    setText('')
  }
  const update = (id, patch) => setTodos(todos.map((t) => (t.id === id ? { ...t, ...patch } : t)))
  const saveEdit = () => {
    const t = editing.text.trim()
    if (t) update(editing.id, { text: t })
    setEditing(null)
  }

  // derived, not stored
  const visible = todos.filter((t) => (filter === 'active' ? !t.done : filter === 'completed' ? t.done : true))
  const left = todos.filter((t) => !t.done).length

  return (
    <div className="todo">
      <input aria-label="New todo" value={text} onChange={(e) => setText(e.target.value)}
        onKeyDown={(e) => e.key === 'Enter' && add()} />
      <button onClick={add}>Add</button>
      <ul>
        {visible.map((t) => (
          <li key={t.id}>
            <input type="checkbox" aria-label={t.text} checked={t.done}
              onChange={() => update(t.id, { done: !t.done })} />
            {editing?.id === t.id ? (
              <input aria-label={'Edit ' + t.text} autoFocus value={editing.text}
                onChange={(e) => setEditing({ ...editing, text: e.target.value })}
                onKeyDown={(e) => e.key === 'Enter' && saveEdit()} onBlur={saveEdit} />
            ) : (
              <span onDoubleClick={() => setEditing({ id: t.id, text: t.text })}
                style={{ textDecoration: t.done ? 'line-through' : 'none' }}>{t.text}</span>
            )}
            <button aria-label={'Delete ' + t.text} onClick={() => setTodos(todos.filter((x) => x.id !== t.id))}>✕</button>
          </li>
        ))}
      </ul>
      {['all', 'active', 'completed'].map((f) => (
        <button key={f} aria-pressed={filter === f} onClick={() => setFilter(f)}>
          {f[0].toUpperCase() + f.slice(1)}
        </button>
      ))}
      <p>{left + (left === 1 ? ' item' : ' items') + ' left'}</p>
    </div>
  )
}

