import { useId, useState } from 'react'

export default function Accordion({ items, multiple = false, defaultOpen = [] }) {
  const [open, setOpen] = useState(defaultOpen)
  const base = useId()

  const toggle = (id) =>
    setOpen((cur) =>
      cur.includes(id) ? cur.filter((x) => x !== id) : multiple ? [...cur, id] : [id])

  return (
    <div className="accordion">
      {items.map((it) => {
        const isOpen = open.includes(it.id)
        const headId = base + 'h' + it.id
        const panelId = base + 'p' + it.id
        return (
          <div key={it.id}>
            <h3>
              <button id={headId} aria-expanded={isOpen} aria-controls={panelId} onClick={() => toggle(it.id)}>
                {it.title}
              </button>
            </h3>
            <div id={panelId} role="region" aria-labelledby={headId} hidden={!isOpen}>
              {it.content}
            </div>
          </div>
        )
      })}
    </div>
  )
}

