import { useEffect, useId, useRef } from 'react'
import { createPortal } from 'react-dom'

const FOCUSABLE = 'a[href], button:not([disabled]), input:not([disabled]), select, textarea, [tabindex]:not([tabindex="-1"])'

export default function Modal({ open, onClose, title, children }) {
  const box = useRef(null)
  const closeRef = useRef(onClose)
  const titleId = useId()
  useEffect(() => { closeRef.current = onClose })

  useEffect(() => {
    if (!open) return
    const opener = document.activeElement
    const oldOverflow = document.body.style.overflow
    document.body.style.overflow = 'hidden'
    box.current.querySelector(FOCUSABLE)?.focus()
    const onKey = (e) => { if (e.key === 'Escape') closeRef.current() }
    document.addEventListener('keydown', onKey)
    return () => {
      document.removeEventListener('keydown', onKey)
      document.body.style.overflow = oldOverflow
      opener?.focus?.()
    }
  }, [open])

  const trap = (e) => {
    if (e.key !== 'Tab') return
    const els = [...box.current.querySelectorAll(FOCUSABLE)]
    if (!els.length) return
    const first = els[0]
    const last = els[els.length - 1]
    if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus() }
    else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus() }
  }

  if (!open) return null
  return createPortal(
    <div className="backdrop" data-testid="backdrop"
      onClick={(e) => { if (e.target === e.currentTarget) closeRef.current() }}>
      <div className="dialog" role="dialog" aria-modal="true" aria-labelledby={titleId} ref={box} onKeyDown={trap}>
        <header>
          <h2 id={titleId}>{title}</h2>
          <button aria-label="Close" onClick={() => closeRef.current()}>✕</button>
        </header>
        <div>{children}</div>
      </div>
    </div>,
    document.body,
  )
}

