test('clicking a star calls onChange with its number', async () => {
  const user = userEvent.setup()
  const onChange = vi.fn()
  render(<StarRating value={1} onChange={onChange} />)
  await user.click(screen.getByRole('radio', { name: '4 stars' }))
  expect(onChange).toHaveBeenCalledWith(4)
})

test('hover previews, leaving shows the value again', async () => {
  const user = userEvent.setup()
  const onChange = vi.fn()
  render(<StarRating value={2} onChange={onChange} />)
  await user.hover(screen.getByRole('radio', { name: '4 stars' }))
  expect(stars()).toBe('★★★★☆')
  await user.unhover(screen.getByRole('radiogroup'))
  expect(stars()).toBe('★★☆☆☆')
  expect(onChange).not.toHaveBeenCalled()
})

test('readOnly ignores hover and clicks', async () => {
  const user = userEvent.setup()
  const onChange = vi.fn()
  render(<StarRating value={2} onChange={onChange} readOnly />)
  await user.hover(screen.getByRole('radio', { name: '5 stars' }))
  expect(stars()).toBe('★★☆☆☆')
  await user.click(screen.getByRole('radio', { name: '5 stars' }))
  expect(onChange).not.toHaveBeenCalled()
})

test('ArrowRight and ArrowLeft change the value', async () => {
  const user = userEvent.setup()
  const onChange = vi.fn()
  render(<StarRating value={3} onChange={onChange} />)
  screen.getByRole('radio', { name: '3 stars' }).focus()
  await user.keyboard('{ArrowRight}')
  expect(onChange).toHaveBeenLastCalledWith(4)
  await user.keyboard('{ArrowLeft}')
  expect(onChange).toHaveBeenLastCalledWith(2)
})

