import { useState } from 'react'

export default function StarRating({ value = 0, onChange, max = 5, readOnly = false }) {
  const [hover, setHover] = useState(null)
  const shown = hover ?? value

  const set = (n) => {
    if (readOnly) return
    onChange?.(Math.min(max, Math.max(1, n)))
  }
  const onKeyDown = (e) => {
    if (e.key === 'ArrowRight' || e.key === 'ArrowUp') { e.preventDefault(); set(value + 1) }
    if (e.key === 'ArrowLeft' || e.key === 'ArrowDown') { e.preventDefault(); set(value - 1) }
  }

  return (
    <div role="radiogroup" aria-label="Rating" aria-readonly={readOnly}
      onMouseLeave={() => setHover(null)} onKeyDown={onKeyDown}>
      {Array.from({ length: max }, (_, i) => {
        const n = i + 1
        return (
          <span key={n} role="radio" aria-checked={n === value} aria-label={n + (n === 1 ? ' star' : ' stars')}
            tabIndex={readOnly ? -1 : n === (value || 1) ? 0 : -1}
            onClick={() => set(n)}
            onMouseEnter={() => !readOnly && setHover(n)}
            style={{ cursor: readOnly ? 'default' : 'pointer', fontSize: 24, color: '#f5a623' }}>
            {n <= shown ? '★' : '☆'}
          </span>
        )
      })}
    </div>
  )
}

