import Tabs from './tabs/Tabs'

const tabs = [
  { id: 'p', label: 'Profile', content: <input placeholder="Type, switch tab, come back" /> },
  { id: 'b', label: 'Billing', content: 'Billing settings' },
  { id: 't', label: 'Team', content: 'Team members' },
]

export default function App() {
  return <Tabs tabs={tabs} />
}

import { render, screen } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import Tabs from './Tabs'

const tabs = [
  { id: 'p', label: 'Profile', content: 'Profile panel' },
  { id: 'b', label: 'Billing', content: 'Billing panel' },
  { id: 't', label: 'Team', content: 'Team panel' },
]
const tab = (name) => screen.getByRole('tab', { name })
const shownPanel = () => screen.getByRole('tabpanel').textContent

test('first tab is selected and only its panel shows', () => {
  render(<Tabs tabs={tabs} />)
  expect(tab('Profile').getAttribute('aria-selected')).toBe('true')
  expect(screen.getAllByRole('tabpanel')).toHaveLength(1)
  expect(shownPanel()).toBe('Profile panel')
})

test('clicking a tab shows its panel', async () => {
  const user = userEvent.setup()
  render(<Tabs tabs={tabs} />)
  await user.click(tab('Billing'))
  expect(tab('Billing').getAttribute('aria-selected')).toBe('true')
  expect(tab('Profile').getAttribute('aria-selected')).toBe('false')
  expect(shownPanel()).toBe('Billing panel')
})

test('roving tabindex: only the selected tab is 0', async () => {
  const user = userEvent.setup()
  render(<Tabs tabs={tabs} defaultTab="b" />)
