import { useRef, useState } from 'react'

export default function Tabs({ tabs, defaultTab, orientation = 'horizontal' }) {
  const first = defaultTab ?? tabs[0]?.id
  const [active, setActive] = useState(first)
  const [visited, setVisited] = useState(() => new Set([first]))
  const refs = useRef({})

  const select = (id) => {
    setActive(id)
    setVisited((v) => (v.has(id) ? v : new Set(v).add(id)))
    refs.current[id]?.focus()
  }

  const onKeyDown = (e) => {
    const i = tabs.findIndex((t) => t.id === active)
    const next = orientation === 'vertical' ? 'ArrowDown' : 'ArrowRight'
    const prev = orientation === 'vertical' ? 'ArrowUp' : 'ArrowLeft'
    let j = null
    if (e.key === next) j = (i + 1) % tabs.length
    if (e.key === prev) j = (i - 1 + tabs.length) % tabs.length
    if (e.key === 'Home') j = 0
    if (e.key === 'End') j = tabs.length - 1
    if (j === null) return
    e.preventDefault()
    select(tabs[j].id)
  }

  return (
    <div className={'tabs ' + orientation}>
      <div role="tablist" aria-orientation={orientation} onKeyDown={onKeyDown}>
        {tabs.map((t) => (
          <button key={t.id} id={'tab-' + t.id} role="tab" aria-selected={t.id === active}
            aria-controls={'panel-' + t.id} tabIndex={t.id === active ? 0 : -1}
            ref={(el) => { refs.current[t.id] = el }} onClick={() => select(t.id)}>
            {t.label}
          </button>
        ))}
      </div>
      {tabs.filter((t) => visited.has(t.id)).map((t) => (
        <div key={t.id} id={'panel-' + t.id} role="tabpanel" aria-labelledby={'tab-' + t.id} hidden={t.id !== active}>
          {t.content}
        </div>
      ))}
    </div>
  )
}

