import { useEffect, useRef, useState } from 'react'

const fmt = (s) => String(Math.floor(s / 60)).padStart(2, '0') + ':' + String(s % 60).padStart(2, '0')

export default function CountdownTimer({ seconds, onComplete }) {
  const [left, setLeft] = useState(seconds)
  const [running, setRunning] = useState(false)
  const leftRef = useRef(left)
  leftRef.current = left
  const doneRef = useRef(onComplete)
  useEffect(() => { doneRef.current = onComplete })

  useEffect(() => {
    if (!running) return
    const end = Date.now() + leftRef.current * 1000
    const id = setInterval(() => {
      const l = Math.max(0, Math.round((end - Date.now()) / 1000))
      setLeft(l)
      if (l === 0) {
        clearInterval(id)
        setRunning(false)
        doneRef.current?.()
      }
    }, 250)
    return () => clearInterval(id)
  }, [running])

  return (
    <div className="countdown">
      <div role="timer" aria-live="off" style={{ fontSize: 40, fontVariantNumeric: 'tabular-nums' }}>{fmt(left)}</div>
      <button onClick={() => left > 0 && setRunning(true)} disabled={running}>Start</button>
      <button onClick={() => setRunning(false)} disabled={!running}>Pause</button>
      <button onClick={() => { setRunning(false); setLeft(seconds) }}>Reset</button>
    </div>
  )
}

