export function getPages(current, total) {
  const keep = (p) => p === 1 || p === total || Math.abs(p - current) <= 1
  const out = []
  for (let p = 1; p <= total; p++) {
    if (keep(p)) out.push(p)
    else if (keep(p - 1) && keep(p + 1)) out.push(p) // gap of one page: show it
    else if (out[out.length - 1] !== '…') out.push('…')
  }
  return out
}

export default function Pagination({ totalItems, itemsPerPage, currentPage, onPageChange }) {
  const total = Math.ceil(totalItems / itemsPerPage)
  if (total < 1) return null
  const go = (p) => p >= 1 && p <= total && p !== currentPage && onPageChange(p)

  return (
    <nav aria-label="Pagination" className="pagination">
      <button onClick={() => go(currentPage - 1)} disabled={currentPage === 1}>Previous</button>
      <ul>
        {getPages(currentPage, total).map((p, i) => (
          <li key={p === '…' ? 'gap' + i : p}>
            {p === '…' ? <span>…</span> : (
              <button aria-current={p === currentPage ? 'page' : undefined} onClick={() => go(p)}>{p}</button>
            )}
          </li>
        ))}
      </ul>
      <button onClick={() => go(currentPage + 1)} disabled={currentPage === total}>Next</button>
    </nav>
  )
}

