import { useRef, useState } from 'react'

export default function OtpInput({ length = 6, onComplete }) {
  const [values, setValues] = useState(() => Array(length).fill(''))
  const refs = useRef([])

  const commit = (next) => {
    setValues(next)
    if (next.every((v) => v !== '')) onComplete?.(next.join(''))
  }

  const onChange = (i, e) => {
    const d = e.target.value.replace(/\D/g, '').slice(-1) // last typed digit
    if (!d) return
    const next = [...values]
    next[i] = d
    commit(next)
    refs.current[i + 1]?.focus()
  }

  const onKeyDown = (i, e) => {
    if (e.key === 'Backspace' && !values[i] && i > 0) {
      e.preventDefault()
      const next = [...values]
      next[i - 1] = ''
      setValues(next)
      refs.current[i - 1].focus()
    }
    if (e.key === 'ArrowLeft') refs.current[i - 1]?.focus()
    if (e.key === 'ArrowRight') refs.current[i + 1]?.focus()
  }

  const onPaste = (i, e) => {
    e.preventDefault()
    const digits = e.clipboardData.getData('text').replace(/\D/g, '').slice(0, length - i).split('')
    if (!digits.length) return
    const next = [...values]
    digits.forEach((d, k) => { next[i + k] = d })
    commit(next)
    refs.current[Math.min(i + digits.length, length - 1)].focus()
  }

  return (
    <div className="otp">
      {values.map((v, i) => (
        <input key={i} aria-label={'Digit ' + (i + 1)} inputMode="numeric" autoComplete="one-time-code"
          value={v} ref={(el) => { refs.current[i] = el }}
          onChange={(e) => onChange(i, e)} onKeyDown={(e) => onKeyDown(i, e)} onPaste={(e) => onPaste(i, e)}
          onFocus={(e) => e.target.select()}
          style={{ width: 40, height: 48, textAlign: 'center', fontSize: 22 }} />
      ))}
    </div>
  )
}

