import { useEffect, useId, useRef, useState } from 'react'

function Highlight({ text, query }) {
  const i = text.toLowerCase().indexOf(query.toLowerCase())
  if (!query || i < 0) return text
  return <>{text.slice(0, i)}<mark>{text.slice(i, i + query.length)}</mark>{text.slice(i + query.length)}</>
}

export default function SearchableDropdown({ options, onSelect }) {
  const [query, setQuery] = useState('')
  const [open, setOpen] = useState(false)
  const [active, setActive] = useState(0)
  const root = useRef(null)
  const id = useId()

  const shown = options.filter((o) => o.toLowerCase().includes(query.toLowerCase()))

  useEffect(() => {
    if (!open) return
    const onDown = (e) => { if (!root.current.contains(e.target)) setOpen(false) }
    document.addEventListener('mousedown', onDown)
    return () => document.removeEventListener('mousedown', onDown)
  }, [open])

  const pick = (o) => {
    setQuery(o)
    setOpen(false)
    onSelect?.(o)
  }

  const onKeyDown = (e) => {
    if (e.key === 'ArrowDown') { e.preventDefault(); setOpen(true); setActive((a) => Math.min(a + 1, shown.length - 1)) }
    if (e.key === 'ArrowUp') { e.preventDefault(); setActive((a) => Math.max(a - 1, 0)) }
    if (e.key === 'Enter' && open && shown[active]) { e.preventDefault(); pick(shown[active]) }
    if (e.key === 'Escape') setOpen(false)
  }

  return (
    <div ref={root} className="dropdown" style={{ position: 'relative' }}>
      <input role="combobox" aria-label="Search" aria-expanded={open} aria-controls={id}
        aria-activedescendant={open && shown[active] ? id + '-' + active : undefined}
        value={query} onFocus={() => setOpen(true)} onKeyDown={onKeyDown}
        onChange={(e) => { setQuery(e.target.value); setActive(0); setOpen(true) }} />
      {open && (
        <ul role="listbox" id={id}>
          {shown.length === 0 && <li>No options found</li>}
          {shown.map((o, i) => (
            <li key={o} id={id + '-' + i} role="option" aria-selected={i === active}
              onMouseDown={(e) => e.preventDefault()} onMouseEnter={() => setActive(i)} onClick={() => pick(o)}>
              <Highlight text={o} query={query} />
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}

