const ZONES = [
  { upTo: 30, color: 'red' },
  { upTo: 70, color: 'orange' },
  { upTo: 100, color: 'green' },
]

export default function ProgressBar({ value = 0, max = 100, label, color, thresholds = ZONES, indeterminate = false }) {
  const v = Math.min(max, Math.max(0, value))
  const pct = max > 0 ? Math.round((v / max) * 100) : 0
  const fill = color ?? (thresholds.find((z) => pct <= z.upTo) ?? thresholds[thresholds.length - 1]).color

  return (
    <div className="progress" style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
      {label && <span>{label}</span>}
      <div role="progressbar" aria-label={label} aria-valuemin={0} aria-valuemax={max}
        aria-valuenow={indeterminate ? undefined : v}
        style={{ flex: 1, height: 10, background: '#eee', borderRadius: 5, overflow: 'hidden' }}>
        <div data-testid="fill" className={indeterminate ? 'indeterminate' : undefined}
          style={{ height: '100%', width: indeterminate ? '30%' : pct + '%', backgroundColor: fill, transition: 'width .3s' }} />
      </div>
      {!indeterminate && <span>{pct}%</span>}
    </div>
  )
}

