import { useEffect, useState } from 'react'

const NEXT = { red: 'green', green: 'yellow', yellow: 'red' }
const NAME = { red: 'Red', green: 'Green', yellow: 'Yellow' }

export default function TrafficLight({ durations = { red: 3000, green: 3000, yellow: 1000 } }) {
  const [color, setColor] = useState('red')
  const [paused, setPaused] = useState(false)

  useEffect(() => {
    if (paused) return
    const id = setTimeout(() => setColor((c) => NEXT[c]), durations[color])
    return () => clearTimeout(id)
  }, [color, paused, durations])

  return (
    <div className="traffic">
      <div className="pole" style={{ display: 'inline-flex', flexDirection: 'column', gap: 6, background: '#222', padding: 8, borderRadius: 12 }}>
        {['red', 'yellow', 'green'].map((c) => (
          <div key={c} data-color={c} data-on={c === color}
            style={{ width: 40, height: 40, borderRadius: '50%', background: c, opacity: c === color ? 1 : 0.2 }} />
        ))}
      </div>
      <p role="status">{NAME[color]}</p>
      <button onClick={() => setPaused(true)}>Pause</button>
      <button onClick={() => setPaused(false)}>Resume</button>
      {['red', 'yellow', 'green'].map((c) => (
        <button key={c} onClick={() => { setColor(c); setPaused(true) }}>{NAME[c]}</button>
      ))}
    </div>
  )
}

