import { useEffect, useState } from 'react'

export default function GridLight({ rows = 3, cols = 3 }) {
  const [order, setOrder] = useState([])
  const [resetting, setResetting] = useState(false)
  const total = rows * cols

  // all lit → start turning off
  useEffect(() => {
    if (!resetting && total > 0 && order.length === total) setResetting(true)
  }, [order, resetting, total])

  // turn off the last one every 500 ms
  useEffect(() => {
    if (!resetting) return
    if (order.length === 0) { setResetting(false); return }
    const id = setTimeout(() => setOrder((o) => o.slice(0, -1)), 500)
    return () => clearTimeout(id)
  }, [resetting, order])

  const click = (key) => {
    if (resetting || order.includes(key)) return
    setOrder([...order, key])
  }

  const cells = []
  for (let r = 1; r <= rows; r++) {
    for (let c = 1; c <= cols; c++) {
      const key = r + '-' + c
      const on = order.includes(key)
      cells.push(
        <button key={key} aria-label={'Cell ' + key} aria-pressed={on} disabled={resetting}
          onClick={() => click(key)}
          style={{ aspectRatio: '1', background: on ? '#58cc02' : '#eee', border: '1px solid #ccc' }} />,
      )
    }
  }

  return (
    <div>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(' + cols + ', 60px)', gap: 6 }}>{cells}</div>
      <button onClick={() => { setOrder([]); setResetting(false) }}>Restart</button>
    </div>
  )
}

