import { useEffect, useId, useRef, useState } from 'react'

export default function Navbar({ brand, links }) {
  const [open, setOpen] = useState(false)
  const [scrolled, setScrolled] = useState(false)
  const [active, setActive] = useState(null)
  const navRef = useRef(null)
  const menuId = useId()

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 10)
    onScroll()
    window.addEventListener('scroll', onScroll, { passive: true })
    return () => window.removeEventListener('scroll', onScroll)
  }, [])

  useEffect(() => {
    if (!open) return
    const onKey = (e) => e.key === 'Escape' && setOpen(false)
    const onDown = (e) => { if (!navRef.current.contains(e.target)) setOpen(false) }
    document.addEventListener('keydown', onKey)
    document.addEventListener('mousedown', onDown)
    return () => {
      document.removeEventListener('keydown', onKey)
      document.removeEventListener('mousedown', onDown)
    }
  }, [open])

  useEffect(() => {
    const obs = new IntersectionObserver((entries) => {
      for (const e of entries) if (e.isIntersecting) setActive('#' + e.target.id)
    }, { rootMargin: '-50% 0px -50% 0px' })
    for (const l of links) {
      const el = document.querySelector(l.href)
      if (el) obs.observe(el)
    }
    return () => obs.disconnect()
  }, [links])

  return (
    <nav ref={navRef} className={'navbar' + (scrolled ? ' scrolled' : '')}>
      <a href="#top" className="brand">{brand}</a>
      <button className="burger" aria-label="Menu" aria-expanded={open} aria-controls={menuId} onClick={() => setOpen(!open)}>☰</button>
      <ul id={menuId} className={open ? 'open' : ''}>
        {links.map((l) => (
          <li key={l.href}>
            <a href={l.href} aria-current={active === l.href ? 'true' : undefined} onClick={() => setOpen(false)}>{l.label}</a>
          </li>
        ))}
      </ul>
    </nav>
  )
}

