import { Fragment } from 'react'

export default function Stepper({ steps, current = 0, onChange, orientation = 'horizontal' }) {
  const statusOf = (i) => (i < current ? 'completed' : i === current ? 'active' : 'upcoming')
  return (
    <ol className={'stepper ' + orientation} data-orientation={orientation}
      style={{ display: 'flex', flexDirection: orientation === 'vertical' ? 'column' : 'row', alignItems: 'center', listStyle: 'none', padding: 0 }}>
      {steps.map((label, i) => (
        <Fragment key={label}>
          {i > 0 && <li className="connector" aria-hidden="true" style={{ flex: 1, minWidth: 24, minHeight: 24, borderTop: '2px solid #ccc' }} />}
          <li data-status={statusOf(i)}>
            <button aria-label={label} aria-current={i === current ? 'step' : undefined} onClick={() => onChange?.(i)}>
              <span className="dot">{i < current ? '✓' : i + 1}</span> <span>{label}</span>
            </button>
          </li>
        </Fragment>
      ))}
    </ol>
  )
}

