import { act, fireEvent, render, screen } from '@testing-library/react'
import Autocomplete from './Autocomplete'

const DATA = ['React', 'React Native', 'Redux', 'Vue', 'Svelte']
const api = () => vi.fn((q) => Promise.resolve(DATA.filter((d) => d.toLowerCase().includes(q.toLowerCase()))))

beforeEach(() => vi.useFakeTimers())
afterEach(() => vi.useRealTimers())

const input = () => screen.getByRole('combobox', { name: 'Search' })
const type = (v) => fireEvent.change(input(), { target: { value: v } })
const wait = (ms) => act(async () => { vi.advanceTimersByTime(ms) }) // also lets promises settle
const options = () => screen.queryAllByRole('option').map((o) => o.textContent)

test('waits 300 ms after the last key before calling the API', async () => {
  const fetchSuggestions = api()
  render(<Autocomplete fetchSuggestions={fetchSuggestions} />)
  type('r'); await wait(100)
  type('re'); await wait(100)
  type('rea'); await wait(299)
  expect(fetchSuggestions).not.toHaveBeenCalled()
  await wait(1)
  expect(fetchSuggestions).toHaveBeenCalledTimes(1)
  expect(fetchSuggestions).toHaveBeenCalledWith('rea')
})

test('shows Loading… and then the results', async () => {
  let resolve
  render(<Autocomplete fetchSuggestions={() => new Promise((r) => { resolve = r })} />)
  type('re'); await wait(300)
  expect(screen.getByText('Loading…')).toBeTruthy()
  await act(async () => resolve(['React', 'Redux']))
  expect(screen.queryByText('Loading…')).toBeNull()
  expect(options()).toEqual(['React', 'Redux'])
})

test('arrows and Enter pick a suggestion', async () => {
  const onSelect = vi.fn()
  render(<Autocomplete fetchSuggestions={api()} onSelect={onSelect} />)
  type('re'); await wait(300)
  fireEvent.keyDown(input(), { key: 'ArrowDown' })
  expect(screen.getByRole('option', { selected: true }).textContent).toBe('React Native')
  fireEvent.keyDown(input(), { key: 'Enter' })
  expect(onSelect).toHaveBeenCalledWith('React Native')
  expect(input().value).toBe('React Native')
})

test('highlights the match with <mark>', async () => {
  render(<Autocomplete fetchSuggestions={api()} />)
  type('du'); await wait(300)
  expect(document.querySelector('mark').textContent).toBe('du')
})

test('caches results: the same query is fetched once', async () => {
  const fetchSuggestions = api()
  render(<Autocomplete fetchSuggestions={fetchSuggestions} />)
  type('re'); await wait(300)
  type('rea'); await wait(300)
  type('re'); await wait(300)
  expect(fetchSuggestions.mock.calls.map((c) => c[0])).toEqual(['re', 'rea'])
  expect(options()).toEqual(['React', 'React Native', 'Redux'])
})

test('an old response that arrives late is ignored', async () => {
  const pending = {}
  render(<Autocomplete fetchSuggestions={(q) => new Promise((r) => { pending[q] = r })} />)
  type('re'); await wait(300)
  type('rea'); await wait(300)
  await act(async () => pending.rea(['React']))
  await act(async () => pending.re(['React', 'Redux']))
  expect(options()).toEqual(['React'])
})

test('shows an error and Retry calls the API again', async () => {
  const fetchSuggestions = vi.fn().mockRejectedValueOnce(new Error('down')).mockResolvedValue(['Vue'])
  render(<Autocomplete fetchSuggestions={fetchSuggestions} />)
  type('vu'); await wait(300)
  expect(screen.getByText(/Something went wrong/)).toBeTruthy()
  await act(async () => fireEvent.click(screen.getByRole('button', { name: 'Retry' })))
  expect(fetchSuggestions).toHaveBeenCalledTimes(2)
  expect(options()).toEqual(['Vue'])
})

test('Clear empties the input and the list; empty query does not fetch', async () => {
  const fetchSuggestions = api()
