import { useCallback, useEffect, useRef, useState } from 'react'

function Highlight({ text, query }) {
  const i = text.toLowerCase().indexOf(query.toLowerCase())
  if (!query || i < 0) return text
  return <>{text.slice(0, i)}<mark>{text.slice(i, i + query.length)}</mark>{text.slice(i + query.length)}</>
}

export default function Autocomplete({ fetchSuggestions, onSelect, delay = 300 }) {
  const [query, setQuery] = useState('')
  const [items, setItems] = useState([])
  const [status, setStatus] = useState('idle')
  const [active, setActive] = useState(0)
  const [open, setOpen] = useState(false)
  const cache = useRef(new Map())
  const latest = useRef('')
  const fetchRef = useRef(fetchSuggestions)
  useEffect(() => { fetchRef.current = fetchSuggestions })

  const load = useCallback(async (q) => {
    latest.current = q
    if (!q.trim()) { setItems([]); setStatus('idle'); return }
    if (cache.current.has(q)) { setItems(cache.current.get(q)); setStatus('done'); setActive(0); return }
    setStatus('loading')
    try {
      const res = await fetchRef.current(q)
      cache.current.set(q, res)
      if (latest.current !== q) return // an older request: ignore
      setItems(res)
      setActive(0)
      setStatus('done')
    } catch {
      if (latest.current === q) setStatus('error')
    }
  }, [])

  useEffect(() => {
    const id = setTimeout(() => load(query), delay)
    return () => clearTimeout(id)
  }, [query, delay, load])

  const pick = (s) => { setQuery(s); setOpen(false); onSelect?.(s) }
  const onKeyDown = (e) => {
    if (e.key === 'ArrowDown') { e.preventDefault(); setActive((a) => Math.min(a + 1, items.length - 1)) }
    if (e.key === 'ArrowUp') { e.preventDefault(); setActive((a) => Math.max(a - 1, 0)) }
    if (e.key === 'Enter' && items[active]) pick(items[active])
    if (e.key === 'Escape') setOpen(false)
  }

  return (
    <div className="autocomplete">
      <input role="combobox" aria-label="Search" aria-expanded={open && items.length > 0} value={query}
        onChange={(e) => { setQuery(e.target.value); setOpen(true) }} onKeyDown={onKeyDown} />
      {query && <button onClick={() => { setQuery(''); setItems([]); setStatus('idle') }}>Clear</button>}
      {status === 'loading' && <p>Loading…</p>}
      {status === 'error' && <p>Something went wrong <button onClick={() => load(query)}>Retry</button></p>}
      {open && status === 'done' && items.length > 0 && (
        <ul role="listbox">
          {items.map((s, i) => (
            <li key={s} role="option" aria-selected={i === active} onMouseDown={(e) => e.preventDefault()} onClick={() => pick(s)}>
              <Highlight text={s} query={query} />
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}

