import { useEffect, useRef, useState } from 'react'

export default function InfiniteList({ fetchPage }) {
  const [items, setItems] = useState([])
  const [page, setPage] = useState(1)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState(false)
  const [done, setDone] = useState(false)
  const inFlight = useRef(false)
  const sentinel = useRef(null)

  const loadMore = async () => {
    if (inFlight.current || done || error) return
    inFlight.current = true
    setLoading(true)
    try {
      const res = await fetchPage(page)
      setItems((old) => [...old, ...res.items])
      setPage((p) => p + 1)
      if (!res.hasMore) setDone(true)
    } catch {
      setError(true)
    } finally {
      inFlight.current = false
      setLoading(false)
    }
  }

  // the observer is created once; it always calls the latest loadMore
  const loadRef = useRef(loadMore)
  loadRef.current = loadMore
  useEffect(() => {
    const obs = new IntersectionObserver((entries) => {
      if (entries[0].isIntersecting) loadRef.current()
    }, { rootMargin: '200px' })
    obs.observe(sentinel.current)
    return () => obs.disconnect()
  }, [])

  return (
    <div>
      <ul>{items.map((it, i) => <li key={i}>{it}</li>)}</ul>
      {loading && <p>Loading…</p>}
      {error && <p>Failed to load <button onClick={() => { setError(false); inFlight.current = false; setTimeout(() => loadRef.current()) }}>Retry</button></p>}
      {done && <p>All items loaded</p>}
      <div ref={sentinel} data-testid="sentinel" style={{ height: 1 }} />
    </div>
  )
}

