import { useState } from 'react'

const STEPS = ['Personal', 'Professional', 'Review']
const FIELDS = [['name', 'email'], ['company', 'role'], []]
const LABEL = { name: 'Name', email: 'Email', company: 'Company', role: 'Role' }

function validate(data) {
  const e = {}
  if (!data.name.trim()) e.name = 'Name is required'
  if (!/^\S+@\S+\.\S+$/.test(data.email)) e.email = 'Enter a valid email'
  if (!data.company.trim()) e.company = 'Company is required'
  if (!data.role.trim()) e.role = 'Role is required'
  return e
}

export default function MultiStepForm({ onSubmit }) {
  const [step, setStep] = useState(0)
  const [data, setData] = useState({ name: '', email: '', company: '', role: '' })
  const [touched, setTouched] = useState({})
  const [status, setStatus] = useState('idle') // idle | submitting | done

  const errors = validate(data)
  const show = (f) => touched[f] && errors[f]

  const next = () => {
    const fields = FIELDS[step]
    setTouched((t) => ({ ...t, ...Object.fromEntries(fields.map((f) => [f, true])) }))
    if (fields.some((f) => errors[f])) return
    setStep(step + 1)
  }

  const submit = async (e) => {
    e.preventDefault()
    if (step < 2) return next()
    setStatus('submitting')
    await onSubmit?.(data)
    setStatus('done')
  }

  if (status === 'done') return <p>Thanks!</p>

  return (
    <form onSubmit={submit} noValidate>
      <p>Step {step + 1} of 3: {STEPS[step]}</p>
      <progress value={step + 1} max={3} />
      {FIELDS[step].map((f) => (
        <div key={f}>
          <label>{LABEL[f]} <input name={f} value={data[f]}
            onChange={(e) => setData({ ...data, [f]: e.target.value })}
            onBlur={() => setTouched({ ...touched, [f]: true })} /></label>
          {show(f) && <span role="alert">{errors[f]}</span>}
        </div>
      ))}
      {step === 2 && (
        <dl>
          {Object.keys(LABEL).map((f) => <div key={f}><dt>{LABEL[f]}</dt><dd>{data[f]}</dd></div>)}
        </dl>
      )}
      {step > 0 && <button type="button" onClick={() => setStep(step - 1)}>Back</button>}
      {step < 2
        ? <button type="submit">Next</button>
        : <button type="submit" disabled={status === 'submitting'}>{status === 'submitting' ? 'Submitting…' : 'Submit'}</button>}
    </form>
  )
}

