import { useEffect, useMemo, useRef, useState } from 'react'

function SelectAll({ checked, indeterminate, onChange }) {
  const ref = useRef(null)
  useEffect(() => { ref.current.indeterminate = indeterminate }, [indeterminate])
  return <input ref={ref} type="checkbox" aria-label="Select all" checked={checked} onChange={onChange} />
}

export default function DataTable({ columns, rows, pageSize = 5 }) {
  const [sort, setSort] = useState({ key: null, dir: null })
  const [query, setQuery] = useState('')
  const [page, setPage] = useState(1)
  const [hidden, setHidden] = useState(() => new Set())
  const [selected, setSelected] = useState(() => new Set())

  const filtered = useMemo(() => {
    const q = query.toLowerCase()
    return q ? rows.filter((r) => columns.some((c) => String(r[c.key]).toLowerCase().includes(q))) : rows
  }, [rows, columns, query])

  const sorted = useMemo(() => {
    if (!sort.key) return filtered
    const k = sort.key
    const out = [...filtered].sort((a, b) =>
      typeof a[k] === 'number' ? a[k] - b[k] : String(a[k]).localeCompare(String(b[k])))
    return sort.dir === 'desc' ? out.reverse() : out
  }, [filtered, sort])

  const pages = Math.max(1, Math.ceil(sorted.length / pageSize))
  const cur = Math.min(page, pages)
  const pageRows = sorted.slice((cur - 1) * pageSize, cur * pageSize)
  const shownCols = columns.filter((c) => !hidden.has(c.key))

  const cycleSort = (key) => setSort((s) =>
    s.key !== key ? { key, dir: 'asc' } : s.dir === 'asc' ? { key, dir: 'desc' } : { key: null, dir: null })
  const toggle = (set, setter, v) => { const n = new Set(set); n.has(v) ? n.delete(v) : n.add(v); setter(n) }
  const onPage = pageRows.filter((r) => selected.has(r.id)).length
  const toggleAll = () => {
    const n = new Set(selected)
    if (onPage === pageRows.length) pageRows.forEach((r) => n.delete(r.id))
    else pageRows.forEach((r) => n.add(r.id))
    setSelected(n)
  }
  const from = sorted.length ? (cur - 1) * pageSize + 1 : 0

  return (
    <div>
      <input aria-label="Search" value={query} onChange={(e) => { setQuery(e.target.value); setPage(1) }} />
      {columns.map((c) => (
        <label key={c.key}><input type="checkbox" checked={!hidden.has(c.key)} onChange={() => toggle(hidden, setHidden, c.key)} /> Show {c.label}</label>
      ))}
      <table>
        <thead>
          <tr>
            <th><SelectAll checked={pageRows.length > 0 && onPage === pageRows.length} indeterminate={onPage > 0 && onPage < pageRows.length} onChange={toggleAll} /></th>
            {shownCols.map((c) => (
              <th key={c.key} aria-sort={sort.key === c.key ? (sort.dir === 'asc' ? 'ascending' : 'descending') : undefined}>
                <button onClick={() => cycleSort(c.key)}>{c.label}</button>
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {pageRows.map((r) => (
            <tr key={r.id}>
              <td><input type="checkbox" aria-label={'Select row ' + r.id} checked={selected.has(r.id)} onChange={() => toggle(selected, setSelected, r.id)} /></td>
              {shownCols.map((c) => <td key={c.key}>{r[c.key]}</td>)}
            </tr>
          ))}
        </tbody>
      </table>
      <p>Showing {from}–{from + pageRows.length - (sorted.length ? 1 : 0)} of {sorted.length}</p>
      <button disabled={cur === 1} onClick={() => setPage(cur - 1)}>Previous</button>
      <button disabled={cur === pages} onClick={() => setPage(cur + 1)}>Next</button>
      <p>{selected.size} selected</p>
    </div>
  )
}

