import { useEffect, useRef, useState } from 'react'
import { createPortal } from 'react-dom'

let listener = null
let nextId = 1
const push = (type) => (message, opts = {}) =>
  listener?.({ id: nextId++, type, message, duration: opts.duration ?? 3000 })

export const toast = { success: push('success'), error: push('error'), warning: push('warning'), info: push('info') }

function ToastItem({ t, onDone }) {
  const [paused, setPaused] = useState(false)
  const left = useRef(t.duration)
  useEffect(() => {
    if (paused) return
    const start = Date.now()
    const id = setTimeout(onDone, left.current)
    return () => { clearTimeout(id); left.current -= Date.now() - start }
  }, [paused, onDone])

  return (
    <div role="status" data-type={t.type} className={'toast ' + t.type}
      onMouseEnter={() => setPaused(true)} onMouseLeave={() => setPaused(false)}>
      <span>{t.message}</span>
      <button onClick={onDone}>Dismiss</button>
    </div>
  )
}

export function Toaster() {
  const [list, setList] = useState([])
  useEffect(() => {
    listener = (t) => setList((l) => [...l, t].slice(-5))
    return () => { listener = null }
  }, [])
  const remove = useRef((id) => setList((l) => l.filter((x) => x.id !== id))).current

  return createPortal(
    <div className="toaster" style={{ position: 'fixed', top: 16, right: 16, display: 'grid', gap: 8 }}>
      {list.map((t) => <ToastItemMemo key={t.id} t={t} remove={remove} />)}
    </div>,
    document.body,
  )
}

// a stable onDone per toast, so the timer effect does not restart on every render
function ToastItemMemo({ t, remove }) {
  const onDone = useRef(() => remove(t.id)).current
  return <ToastItem t={t} onDone={onDone} />
}

