import { useEffect, useRef, useState } from 'react'

const COLUMNS = ['Todo', 'In Progress', 'Done']
const empty = { Todo: [], 'In Progress': [], Done: [] }

function load(initial) {
  try { return JSON.parse(localStorage.getItem('kanban')) ?? initial ?? empty } catch { return initial ?? empty }
}

export default function KanbanBoard({ initial }) {
  const [board, setBoard] = useState(() => load(initial))
  const [over, setOver] = useState(null)
  const [drafts, setDrafts] = useState({})
  const dragged = useRef(null) // { id, from }

  useEffect(() => { localStorage.setItem('kanban', JSON.stringify(board)) }, [board])

  const move = (to, beforeId) => {
    const d = dragged.current
    if (!d) return
    setBoard((b) => {
      const card = b[d.from].find((c) => c.id === d.id)
      const next = { ...b, [d.from]: b[d.from].filter((c) => c.id !== d.id) }
      const list = [...next[to]]
      const at = beforeId ? list.findIndex((c) => c.id === beforeId) : -1
      list.splice(at < 0 ? list.length : at, 0, card)
      return { ...next, [to]: list }
    })
    dragged.current = null
    setOver(null)
  }

  const add = (col) => {
    const text = (drafts[col] ?? '').trim()
    if (!text) return
    setBoard((b) => ({ ...b, [col]: [...b[col], { id: crypto.randomUUID(), text }] }))
    setDrafts({ ...drafts, [col]: '' })
  }

  return (
    <div style={{ display: 'flex', gap: 16 }}>
      {COLUMNS.map((col) => (
        <section key={col} aria-label={col} className={over === col ? 'over' : ''}
          onDragOver={(e) => { e.preventDefault(); setOver(col) }}
          onDragLeave={() => setOver(null)}
          onDrop={(e) => { e.preventDefault(); move(col) }}
          style={{ flex: 1, padding: 8, background: over === col ? '#e8f5ff' : '#f4f4f4' }}>
          <h3>{col}</h3>
          <ul>
            {board[col].map((c) => (
              <li key={c.id} draggable
                onDragStart={(e) => { dragged.current = { id: c.id, from: col }; e.dataTransfer?.setData?.('text/plain', c.id) }}
                onDrop={(e) => { e.preventDefault(); e.stopPropagation(); move(col, c.id) }}>
                {c.text}
                <button aria-label={'Delete ' + c.text}
                  onClick={() => setBoard((b) => ({ ...b, [col]: b[col].filter((x) => x.id !== c.id) }))}>✕</button>
              </li>
            ))}
          </ul>
          <input aria-label={'New card in ' + col} value={drafts[col] ?? ''}
            onChange={(e) => setDrafts({ ...drafts, [col]: e.target.value })}
            onKeyDown={(e) => e.key === 'Enter' && add(col)} />
        </section>
      ))}
    </div>
  )
}

