import { useEffect, useReducer, useState } from 'react'

const CODES = { SAVE10: 0.1, SAVE20: 0.2 }
const money = (n) => '₹' + (Math.round(n * 100) / 100).toFixed(2)

function cartReducer(lines, a) {
  switch (a.type) {
    case 'add': {
      const has = lines.find((l) => l.id === a.product.id)
      return has ? lines.map((l) => (l.id === a.product.id ? { ...l, qty: l.qty + 1 } : l)) : [...lines, { ...a.product, qty: 1 }]
    }
    case 'inc': return lines.map((l) => (l.id === a.id ? { ...l, qty: l.qty + 1 } : l))
    case 'dec': return lines.flatMap((l) => (l.id !== a.id ? [l] : l.qty > 1 ? [{ ...l, qty: l.qty - 1 }] : []))
    case 'remove': return lines.filter((l) => l.id !== a.id)
    default: return lines
  }
}

const load = () => { try { return JSON.parse(localStorage.getItem('cart')) ?? [] } catch { return [] } }

export default function ShoppingCart({ products }) {
  const [lines, dispatch] = useReducer(cartReducer, undefined, load)
  const [code, setCode] = useState('')
  const [pct, setPct] = useState(0)
  const [error, setError] = useState('')

  useEffect(() => { localStorage.setItem('cart', JSON.stringify(lines)) }, [lines])

  const count = lines.reduce((s, l) => s + l.qty, 0)
  const subtotal = lines.reduce((s, l) => s + l.price * l.qty, 0)
  const discount = subtotal * pct
  const tax = (subtotal - discount) * 0.1
  const total = subtotal - discount + tax

  const apply = () => {
    const p = CODES[code.trim().toUpperCase()]
    if (p) { setPct(p); setError('') } else { setPct(0); setError('Invalid code') }
  }

  return (
    <div className="shop">
      <ul>
        {products.map((p) => (
          <li key={p.id}>{p.name} {money(p.price)}
            <button aria-label={'Add ' + p.name + ' to cart'} onClick={() => dispatch({ type: 'add', product: p })}>Add</button>
          </li>
        ))}
      </ul>
      <h2>Cart ({count})</h2>
      {lines.length === 0 ? <p>Your cart is empty</p> : (
        <ul aria-label="Cart">
          {lines.map((l) => (
            <li key={l.id}>
              {l.name} ×{l.qty}
              <button aria-label={'Decrease ' + l.name} onClick={() => dispatch({ type: 'dec', id: l.id })}>−</button>
              <button aria-label={'Increase ' + l.name} onClick={() => dispatch({ type: 'inc', id: l.id })}>+</button>
              <span>{money(l.price * l.qty)}</span>
              <button aria-label={'Remove ' + l.name} onClick={() => dispatch({ type: 'remove', id: l.id })}>Remove</button>
            </li>
          ))}
        </ul>
      )}
      <input aria-label="Discount code" value={code} onChange={(e) => setCode(e.target.value)} />
      <button onClick={apply}>Apply</button>
      {error && <p role="alert">{error}</p>}
      <p>Subtotal: {money(subtotal)}</p>
      <p>Discount: -{money(discount)}</p>
      <p>Tax: {money(tax)}</p>
      <p><b>Total: {money(total)}</b></p>
    </div>
  )
}

