import FileUpload from './file-upload/FileUpload'

// fake upload: progress every 200 ms, fails sometimes
const fakeUpload = (file, { onProgress, signal }) => new Promise((resolve, reject) => {
  let p = 0
  const id = setInterval(() => {
    p += 20
    onProgress(p)
    if (p >= 100) { clearInterval(id); Math.random() < 0.2 ? reject(new Error('500')) : resolve() }
  }, 200)
  signal.addEventListener('abort', () => { clearInterval(id); reject(new Error('aborted')) })
})

export default function App() {
  return <FileUpload accept={['image/png', 'image/jpeg']} maxSize={5_000_000} upload={fakeUpload} />
}

import { act, fireEvent, render, screen } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import FileUpload from './FileUpload'

beforeEach(() => {
  URL.createObjectURL = vi.fn(() => 'blob:preview')
  URL.revokeObjectURL = vi.fn()
})
const png = (name = 'cat.png', size = 1000) => new File(['x'.repeat(size)], name, { type: 'image/png' })
const pdf = () => new File(['x'], 'notes.pdf', { type: 'application/pdf' })
// an upload we control from the test
function controlledUpload() {
  const calls = []
  const upload = vi.fn((file, { onProgress, signal }) => new Promise((resolve, reject) => {
    signal.addEventListener('abort', () => reject(new Error('aborted')))
    calls.push({ file, onProgress, resolve, reject })
  }))
  return { upload, calls }
}
const setup = (props) => {
  const user = userEvent.setup({ applyAccept: false })
  render(<FileUpload accept={['image/png', 'image/jpeg']} maxSize={5000} {...props} />)
  return user
}

test('chosen files start uploading', async () => {
  const { upload } = controlledUpload()
  const user = setup({ upload })
  await user.upload(screen.getByLabelText('Choose files'), [png('a.png'), png('b.png')])
  expect(upload).toHaveBeenCalledTimes(2)
  expect(upload.mock.calls[0][0].name).toBe('a.png')
  expect(screen.getAllByText('Uploading')).toHaveLength(2)
})

test('rejects wrong types and big files', async () => {
  const { upload } = controlledUpload()
  const user = setup({ upload })
  await user.upload(screen.getByLabelText('Choose files'), [pdf(), png('big.png', 9000)])
  expect(screen.getByText('notes.pdf: type not allowed')).toBeTruthy()
  expect(screen.getByText('big.png: too large')).toBeTruthy()
  expect(upload).not.toHaveBeenCalled()
})

test('dropping files works and shows the dragging state', () => {
  const { upload } = controlledUpload()
  setup({ upload })
  const zone = screen.getByTestId('dropzone')
  fireEvent.dragOver(zone)
  expect(zone.classList.contains('dragging')).toBe(true)
  fireEvent.drop(zone, { dataTransfer: { files: [png()] } })
  expect(zone.classList.contains('dragging')).toBe(false)
  expect(upload).toHaveBeenCalledTimes(1)
})

test('progress updates, then Done', async () => {
  const { upload, calls } = controlledUpload()
  const user = setup({ upload })
  await user.upload(screen.getByLabelText('Choose files'), png())
  act(() => calls[0].onProgress(60))
  expect(screen.getByRole('progressbar', { name: 'cat.png' }).getAttribute('aria-valuenow')).toBe('60')
  await act(async () => calls[0].resolve())
  expect(screen.getByText('Done')).toBeTruthy()
})

test('Cancel aborts the upload', async () => {
  const { upload } = controlledUpload()
  const user = setup({ upload })
  await user.upload(screen.getByLabelText('Choose files'), png())
  await user.click(screen.getByRole('button', { name: 'Cancel cat.png' }))
  expect(upload.mock.calls[0][1].signal.aborted).toBe(true)
  expect(await screen.findByText('Cancelled')).toBeTruthy()
})

test('a failure shows Failed, and Retry uploads again', async () => {
  const { upload, calls } = controlledUpload()
  const user = setup({ upload })
  await user.upload(screen.getByLabelText('Choose files'), png())
  await act(async () => calls[0].reject(new Error('500')))
  expect(screen.getByText('Failed')).toBeTruthy()
  await user.click(screen.getByRole('button', { name: 'Retry cat.png' }))
  expect(upload).toHaveBeenCalledTimes(2)
  expect(screen.getByText('Uploading')).toBeTruthy()
})

