import { useEffect, useRef, useState } from 'react'

let nextId = 1

export default function FileUpload({ accept = [], maxSize = Infinity, upload }) {
  const [items, setItems] = useState([])
  const [errors, setErrors] = useState([])
  const [dragging, setDragging] = useState(false)
  const all = useRef([])
  all.current = items

  useEffect(() => () => all.current.forEach((it) => it.preview && URL.revokeObjectURL(it.preview)), [])

  const patch = (id, p) => setItems((list) => list.map((it) => (it.id === id ? { ...it, ...p } : it)))

  const start = (it) => {
    const controller = new AbortController()
    patch(it.id, { status: 'Uploading', progress: 0, controller })
    upload(it.file, { onProgress: (p) => patch(it.id, { progress: Math.round(p) }), signal: controller.signal })
      .then(() => patch(it.id, { status: 'Done', progress: 100 }))
      .catch(() => patch(it.id, { status: controller.signal.aborted ? 'Cancelled' : 'Failed' }))
  }

  const addFiles = (fileList) => {
    const bad = []
    const good = []
    for (const file of fileList) {
      if (accept.length && !accept.includes(file.type)) bad.push(file.name + ': type not allowed')
      else if (file.size > maxSize) bad.push(file.name + ': too large')
      else good.push({ id: nextId++, file, status: 'Uploading', progress: 0, preview: file.type.startsWith('image/') ? URL.createObjectURL(file) : null })
    }
    setErrors(bad)
    setItems((list) => [...list, ...good])
    good.forEach(start)
  }

  return (
    <div>
      <div data-testid="dropzone" className={dragging ? 'dragging' : ''}
        onDragOver={(e) => { e.preventDefault(); setDragging(true) }}
        onDragLeave={() => setDragging(false)}
        onDrop={(e) => { e.preventDefault(); setDragging(false); addFiles(e.dataTransfer.files) }}
        style={{ border: '2px dashed #aaa', padding: 24, background: dragging ? '#eef' : undefined }}>
        Drop files here or{' '}
        <input type="file" multiple aria-label="Choose files" accept={accept.join(',')}
          onChange={(e) => { addFiles(e.target.files); e.target.value = '' }} />
      </div>
      {errors.map((m) => <p key={m} role="alert">{m}</p>)}
      <ul>
        {items.map((it) => (
          <li key={it.id}>
            {it.preview && <img src={it.preview} alt={it.file.name} width={40} height={40} />}
            {it.file.name}
            <div role="progressbar" aria-label={it.file.name} aria-valuemin={0} aria-valuemax={100} aria-valuenow={it.progress}
              style={{ width: 120, height: 6, background: '#eee' }}><div style={{ width: it.progress + '%', height: '100%', background: '#58cc02' }} /></div>
            <span>{it.status}</span>
            {it.status === 'Uploading' && <button aria-label={'Cancel ' + it.file.name} onClick={() => it.controller?.abort()}>Cancel</button>}
            {it.status === 'Failed' && <button aria-label={'Retry ' + it.file.name} onClick={() => start(it)}>Retry</button>}
          </li>
        ))}
      </ul>
    </div>
  )
}

