import { useEffect, useState } from 'react'

export default function Carousel({ images, interval = 3000 }) {
  const [index, setIndex] = useState(0)
  const [paused, setPaused] = useState(false)
  const [kick, setKick] = useState(0) // changes on manual clicks → restarts the timer
  const n = images.length

  useEffect(() => {
    if (!interval || paused || n < 2) return
    const id = setInterval(() => setIndex((i) => (i + 1) % n), interval)
    return () => clearInterval(id)
  }, [interval, paused, n, kick])

  if (n === 0) return <p>No images</p>

  const go = (i) => { setIndex((i + n) % n); setKick((k) => k + 1) }

  return (
    <div data-testid="carousel" className="carousel" style={{ position: 'relative', overflow: 'hidden', maxWidth: 600 }}
      onMouseEnter={() => setPaused(true)} onMouseLeave={() => setPaused(false)}>
      <div data-testid="track" style={{ display: 'flex', transition: 'transform .4s', transform: 'translateX(-' + index * 100 + '%)' }}>
        {images.map((img) => <img key={img.src} src={img.src} alt={img.alt} style={{ minWidth: '100%' }} />)}
      </div>
      {n > 1 && (
        <>
          <button onClick={() => go(index - 1)}>Previous</button>
          <button onClick={() => go(index + 1)}>Next</button>
          <div>
            {images.map((img, i) => (
              <button key={img.src} aria-label={'Go to slide ' + (i + 1)} aria-current={i === index ? 'true' : undefined} onClick={() => go(i)}>•</button>
            ))}
          </div>
        </>
      )}
    </div>
  )
}

