import { useRef, useState } from 'react'

export default function ChipsInput({ onChange, validate, max = Infinity }) {
  const [chips, setChips] = useState([])
  const [text, setText] = useState('')
  const [error, setError] = useState('')
  const input = useRef(null)

  const update = (next) => { setChips(next); onChange?.(next) }

  const add = () => {
    const v = text.trim()
    if (!v) return
    if (chips.some((c) => c.toLowerCase() === v.toLowerCase())) { setError(v + ' is already added'); return }
    const msg = validate?.(v)
    if (msg) { setError(msg); return }
    update([...chips, v])
    setText('')
    setError('')
  }

  const remove = (i) => { update(chips.filter((_, j) => j !== i)); input.current?.focus() }

  const onKeyDown = (e) => {
    if (e.key === 'Enter' || e.key === ',') { e.preventDefault(); add() }
    if (e.key === 'Backspace' && text === '' && chips.length) update(chips.slice(0, -1))
  }

  return (
    <div className="chips">
      <ul style={{ display: 'inline-flex', gap: 6, listStyle: 'none', padding: 0 }}>
        {chips.map((c, i) => (
          <li key={c} tabIndex={0} onKeyDown={(e) => (e.key === 'Backspace' || e.key === 'Delete') && remove(i)}>
            {c} <button aria-label={'Remove ' + c} onClick={() => remove(i)}>×</button>
          </li>
        ))}
      </ul>
      <input ref={input} aria-label="Add tag" value={text} disabled={chips.length >= max}
        placeholder={chips.length >= max ? 'Limit reached' : 'Type and press Enter'}
        onChange={(e) => setText(e.target.value)} onKeyDown={onKeyDown} />
      {error && <p role="alert">{error}</p>}
    </div>
  )
}

