import { useEffect, useRef, useState } from 'react'

function Check({ label, checked, indeterminate = false, onChange }) {
  const ref = useRef(null)
  useEffect(() => { ref.current.indeterminate = indeterminate }, [indeterminate])
  return <label><input ref={ref} type="checkbox" checked={checked} onChange={onChange} /> {label}</label>
}

export default function TransferList({ left, right }) {
  const [lists, setLists] = useState({ Available: left, Selected: right })
  const [checked, setChecked] = useState(() => new Set())
  const [search, setSearch] = useState({ Available: '', Selected: '' })

  const shown = (pane) => lists[pane].filter((x) => x.toLowerCase().includes(search[pane].toLowerCase()))
  const checkedIn = (pane) => lists[pane].filter((x) => checked.has(x))

  const toggle = (x) => { const n = new Set(checked); n.has(x) ? n.delete(x) : n.add(x); setChecked(n) }
  const toggleAll = (pane) => {
    const items = shown(pane)
    const n = new Set(checked)
    const all = items.length > 0 && items.every((x) => n.has(x))
    items.forEach((x) => (all ? n.delete(x) : n.add(x)))
    setChecked(n)
  }
  const move = (from, to, items) => {
    setLists({ [from]: lists[from].filter((x) => !items.includes(x)), [to]: [...lists[to], ...items] })
    const n = new Set(checked)
    items.forEach((x) => n.delete(x))
    setChecked(n)
  }

  const pane = (name) => {
    const items = shown(name)
    const c = items.filter((x) => checked.has(x)).length
    return (
      <section aria-label={name}>
        <h3>{name} ({lists[name].length})</h3>
        <input aria-label={'Search ' + name} value={search[name]} onChange={(e) => setSearch({ ...search, [name]: e.target.value })} />
        <Check label={'Select all ' + name} checked={items.length > 0 && c === items.length} indeterminate={c > 0 && c < items.length} onChange={() => toggleAll(name)} />
        <ul>{items.map((x) => <li key={x}><Check label={x} checked={checked.has(x)} onChange={() => toggle(x)} /></li>)}</ul>
      </section>
    )
  }

  return (
    <div style={{ display: 'flex', gap: 16 }}>
      {pane('Available')}
      <div style={{ display: 'grid', gap: 4, alignContent: 'center' }}>
        <button disabled={!checkedIn('Available').length} onClick={() => move('Available', 'Selected', checkedIn('Available'))}>Move to Selected</button>
        <button disabled={!checkedIn('Selected').length} onClick={() => move('Selected', 'Available', checkedIn('Selected'))}>Move to Available</button>
        <button disabled={!lists.Available.length} onClick={() => move('Available', 'Selected', lists.Available)}>Move all to Selected</button>
        <button disabled={!lists.Selected.length} onClick={() => move('Selected', 'Available', lists.Selected)}>Move all to Available</button>
      </div>
      {pane('Selected')}
    </div>
  )
}

