import { useEffect, useRef, useState } from 'react'

const leaves = (n) => (n.children?.length ? n.children.flatMap(leaves) : [n.id])
const matches = (n, q) => n.label.toLowerCase().includes(q) || (n.children ?? []).some((c) => matches(c, q))

function Box({ label, state, onChange }) {
  const ref = useRef(null)
  useEffect(() => { ref.current.indeterminate = state === 'some' }, [state])
  return <label><input ref={ref} type="checkbox" checked={state === 'all'} onChange={onChange} /> {label}</label>
}

export default function CheckboxTree({ data, defaultExpanded = [] }) {
  const [checked, setChecked] = useState(() => new Set())
  const [expanded, setExpanded] = useState(() => new Set(defaultExpanded))
  const [query, setQuery] = useState('')
  const q = query.trim().toLowerCase()

  const stateOf = (n) => {
    const ls = leaves(n)
    const c = ls.filter((id) => checked.has(id)).length
    return c === 0 ? 'none' : c === ls.length ? 'all' : 'some'
  }
  const toggle = (n) => {
    const next = new Set(checked)
    const all = stateOf(n) === 'all'
    leaves(n).forEach((id) => (all ? next.delete(id) : next.add(id)))
    setChecked(next)
  }
  const flip = (id) => { const n = new Set(expanded); n.has(id) ? n.delete(id) : n.add(id); setExpanded(n) }

  const render = (nodes) => (
    <ul>
      {nodes.filter((n) => !q || matches(n, q)).map((n) => {
        const kids = n.children?.length > 0
        const open = kids && (q ? true : expanded.has(n.id))
        return (
          <li key={n.id}>
            {kids && (
              <button aria-label={(open ? 'Collapse ' : 'Expand ') + n.label} aria-expanded={open} onClick={() => flip(n.id)}>
                {open ? '▾' : '▸'}
              </button>
            )}
            <Box label={n.label} state={stateOf(n)} onChange={() => toggle(n)} />
            {open && render(n.children)}
          </li>
        )
      })}
    </ul>
  )

  return (
    <div>
      <input aria-label="Search" value={query} onChange={(e) => setQuery(e.target.value)} />
      {render(data)}
    </div>
  )
}

