import { useEffect, useState } from 'react'

const KEY = 'cookie-consent'

export default function CookieConsent({ delay = 2000 }) {
  const [visible, setVisible] = useState(false)
  const [settings, setSettings] = useState(false)
  const [analytics, setAnalytics] = useState(false)
  const [marketing, setMarketing] = useState(false)

  useEffect(() => {
    if (localStorage.getItem(KEY)) return
    const id = setTimeout(() => setVisible(true), delay)
    return () => clearTimeout(id)
  }, [delay])

  const save = (choice) => {
    localStorage.setItem(KEY, JSON.stringify({ essential: true, ...choice }))
    setVisible(false)
  }

  if (!visible) return null
  return (
    <div role="dialog" aria-label="Cookie consent" style={{ position: 'fixed', bottom: 0, left: 0, right: 0, padding: 16, background: '#222', color: '#fff' }}>
      <p>We use cookies to improve your experience.</p>
      {settings ? (
        <>
          <label><input type="checkbox" checked disabled /> Essential</label>
          <label><input type="checkbox" checked={analytics} onChange={(e) => setAnalytics(e.target.checked)} /> Analytics</label>
          <label><input type="checkbox" checked={marketing} onChange={(e) => setMarketing(e.target.checked)} /> Marketing</label>
          <button onClick={() => save({ analytics, marketing })}>Save</button>
        </>
      ) : (
        <>
          <button onClick={() => setSettings(true)}>Settings</button>
          <button onClick={() => save({ analytics: false, marketing: false })}>Reject</button>
          <button onClick={() => save({ analytics: true, marketing: true })}>Accept all</button>
        </>
      )}
    </div>
  )
}

