import { useEffect, useLayoutEffect, useRef, useState } from 'react'

export default function ContextMenu({ items, children }) {
  const [pos, setPos] = useState(null)
  const menu = useRef(null)

  useLayoutEffect(() => {
    if (!pos || !menu.current) return
    const r = menu.current.getBoundingClientRect()
    const x = Math.max(0, Math.min(pos.x, window.innerWidth - r.width))
    const y = Math.max(0, Math.min(pos.y, window.innerHeight - r.height))
    if (x !== pos.x || y !== pos.y) setPos({ x, y })
  }, [pos])

  useEffect(() => {
    if (!pos) return
    const close = () => setPos(null)
    const onDown = (e) => { if (!menu.current?.contains(e.target)) close() }
    const onKey = (e) => e.key === 'Escape' && close()
    document.addEventListener('mousedown', onDown)
    document.addEventListener('keydown', onKey)
    window.addEventListener('scroll', close, true)
    return () => {
      document.removeEventListener('mousedown', onDown)
      document.removeEventListener('keydown', onKey)
      window.removeEventListener('scroll', close, true)
    }
  }, [pos])

  return (
    <div onContextMenu={(e) => { e.preventDefault(); setPos({ x: e.clientX, y: e.clientY }) }}>
      {children}
      {pos && (
        <ul role="menu" ref={menu} style={{ position: 'fixed', left: pos.x + 'px', top: pos.y + 'px', listStyle: 'none', margin: 0, padding: 4, background: '#fff', boxShadow: '0 4px 16px rgb(0 0 0 / .2)' }}>
          {items.map((it, i) => it.divider ? <li key={i} role="separator" style={{ borderTop: '1px solid #ddd' }} /> : (
            <li key={i} role="menuitem" aria-disabled={it.disabled ? 'true' : undefined}
              style={{ padding: '4px 12px', opacity: it.disabled ? 0.4 : 1, cursor: it.disabled ? 'default' : 'pointer' }}
              onClick={() => { if (it.disabled) return; it.onSelect?.(); setPos(null) }}>
              {it.label}
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}

