import { useState } from 'react'

const LINES = [[0, 1, 2], [3, 4, 5], [6, 7, 8], [0, 3, 6], [1, 4, 7], [2, 5, 8], [0, 4, 8], [2, 4, 6]]

function result(b) {
  for (const line of LINES) {
    const [a, c, d] = line
    if (b[a] && b[a] === b[c] && b[a] === b[d]) return { winner: b[a], line }
  }
  return b.every(Boolean) ? { draw: true } : null
}

export default function TicTacToe() {
  const [history, setHistory] = useState([Array(9).fill(null)])
  const [step, setStep] = useState(0)
  const [score, setScore] = useState({ X: 0, O: 0, draws: 0 })

  const board = history[step]
  const res = result(board)
  const player = step % 2 === 0 ? 'X' : 'O'

  const play = (i) => {
    if (board[i] || res) return
    const next = board.slice()
    next[i] = player
    setHistory([...history.slice(0, step + 1), next])
    setStep(step + 1)
    const r = result(next)
    if (r?.winner) setScore((s) => ({ ...s, [r.winner]: s[r.winner] + 1 }))
    else if (r?.draw) setScore((s) => ({ ...s, draws: s.draws + 1 }))
  }

  const status = res?.winner ? 'Winner: ' + res.winner : res?.draw ? 'Draw' : 'Next: ' + player

  return (
    <div className="ttt">
      <p role="status">{status}</p>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 60px)', gap: 4 }}>
        {board.map((v, i) => (
          <button key={i} aria-label={'Square ' + (i + 1)} className={res?.line?.includes(i) ? 'win' : ''}
            onClick={() => play(i)} style={{ height: 60, fontSize: 28 }}>{v}</button>
        ))}
      </div>
      <p>X: {score.X} · O: {score.O} · Draws: {score.draws}</p>
      <button disabled={step === 0} onClick={() => setStep(step - 1)}>Undo</button>
      <button onClick={() => { setHistory([Array(9).fill(null)]); setStep(0) }}>Restart</button>
      <ol>
        {history.map((_, m) => (
          <li key={m}><button onClick={() => setStep(m)}>{m === 0 ? 'Go to start' : 'Go to move ' + m}</button></li>
        ))}
      </ol>
    </div>
  )
}

