import { useState } from 'react'

const calc = (a, b, op) => {
  if (op === '+') return a + b
  if (op === '-') return a - b
  if (op === '×') return a * b
  if (op === '÷') return b === 0 ? NaN : a / b
  return b
}
const show = (n) => (Number.isFinite(n) ? String(parseFloat(n.toPrecision(12))) : 'Error')

export default function Calculator() {
  const [display, setDisplay] = useState('0')
  const [acc, setAcc] = useState(null)
  const [op, setOp] = useState(null)
  const [fresh, setFresh] = useState(true) // next digit replaces the display

  const error = display === 'Error'
  const clear = () => { setDisplay('0'); setAcc(null); setOp(null); setFresh(true) }

  const digit = (d) => {
    if (error) return
    if (fresh) { setDisplay(d === '.' ? '0.' : d); setFresh(false); return }
    if (d === '.' && display.includes('.')) return
    setDisplay(display === '0' && d !== '.' ? d : display + d)
  }

  const operator = (o) => {
    if (error) return
    const cur = parseFloat(display)
    if (op && !fresh) {
      const r = show(calc(acc, cur, op))
      setDisplay(r)
      if (r === 'Error') return
      setAcc(parseFloat(r))
    } else {
      setAcc(cur)
    }
    setOp(o)
    setFresh(true)
  }

  const equals = () => {
    if (error || !op) return
    const r = show(calc(acc, parseFloat(display), op))
    setDisplay(r)
    setAcc(null)
    setOp(null)
    setFresh(true)
  }

  const unary = (f) => { if (!error) setDisplay(show(f(parseFloat(display)))) }

  const keys = ['C', '+/-', '%', '÷', '7', '8', '9', '×', '4', '5', '6', '-', '1', '2', '3', '+', '0', '.', '=']
  const press = (k) => {
    if (k === 'C') return clear()
    if (k === '=') return equals()
    if (k === '%') return unary((n) => n / 100)
    if (k === '+/-') return unary((n) => -n)
    if ('+-×÷'.includes(k)) return operator(k)
    digit(k)
  }

  return (
    <div className="calc" style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 56px)', gap: 4 }}>
      <output aria-label="Display" style={{ gridColumn: 'span 4', textAlign: 'right', fontSize: 28 }}>{display}</output>
      {keys.map((k) => <button key={k} onClick={() => press(k)} style={k === '0' ? { gridColumn: 'span 2' } : undefined}>{k}</button>)}
    </div>
  )
}

