import { useState } from 'react'

const toHex = (rgb) => '#' + rgb.map((v) => v.toString(16).padStart(2, '0')).join('').toUpperCase()
const fromHex = (h) => (/^#?[0-9a-f]{6}$/i.test(h) ? [0, 2, 4].map((i) => parseInt(h.replace('#', '').slice(i, i + 2), 16)) : null)

export default function ColorPicker({ initial = [51, 102, 255] }) {
  const [rgb, setRgb] = useState(initial)
  const [draft, setDraft] = useState(null) // text while typing in the hex box
  const [copied, setCopied] = useState(false)
  const hex = toHex(rgb)
  const css = 'rgb(' + rgb.join(', ') + ')'

  const set = (next) => { setRgb(next); setDraft(null); setCopied(false) }
  const applyDraft = () => {
    if (draft === null) return
    const v = fromHex(draft.trim())
    if (v) set(v)
    else setDraft(null) // revert
  }

  return (
    <div className="picker">
      {['Red', 'Green', 'Blue'].map((name, i) => (
        <label key={name} style={{ display: 'block' }}>{name}{' '}
          <input type="range" min={0} max={255} aria-label={name} value={rgb[i]}
            onChange={(e) => set(rgb.map((v, j) => (j === i ? Number(e.target.value) : v)))} /> {rgb[i]}
        </label>
      ))}
      <div data-testid="swatch" style={{ width: 200, height: 100, borderRadius: 8, backgroundColor: css }} />
      <input aria-label="Hex" value={draft ?? hex} onChange={(e) => setDraft(e.target.value)}
        onBlur={applyDraft} onKeyDown={(e) => e.key === 'Enter' && applyDraft()} />
      <p>{css}</p>
      <button onClick={() => set([0, 0, 0].map(() => Math.floor(Math.random() * 256)))}>Random</button>
      <button onClick={async () => { await navigator.clipboard.writeText(hex); setCopied(true) }}>Copy</button>
      {copied && <span>Copied!</span>}
    </div>
  )
}

