import { useEffect, useMemo, useState } from 'react'

const loadWish = () => { try { return new Set(JSON.parse(localStorage.getItem('wishlist')) ?? []) } catch { return new Set() } }

export default function ProductListing({ products }) {
  const top = Math.max(0, ...products.map((p) => p.price))
  const categories = [...new Set(products.map((p) => p.category))]
  const [category, setCategory] = useState('All')
  const [maxPrice, setMaxPrice] = useState(top)
  const [minRating, setMinRating] = useState(0)
  const [sort, setSort] = useState('none')
  const [wish, setWish] = useState(loadWish)

  useEffect(() => { localStorage.setItem('wishlist', JSON.stringify([...wish])) }, [wish])

  const shown = useMemo(() => {
    const list = products.filter((p) =>
      (category === 'All' || p.category === category) && p.price <= maxPrice && p.rating >= minRating)
    if (sort === 'price-asc') list.sort((a, b) => a.price - b.price)
    if (sort === 'price-desc') list.sort((a, b) => b.price - a.price)
    if (sort === 'rating-desc') list.sort((a, b) => b.rating - a.rating)
    return list
  }, [products, category, maxPrice, minRating, sort])

  const toggleWish = (id) => { const n = new Set(wish); n.has(id) ? n.delete(id) : n.add(id); setWish(n) }

  return (
    <div>
      <header>Wishlist ({wish.size})</header>
      <aside>
        <label>Category <select value={category} onChange={(e) => setCategory(e.target.value)}>
          {['All', ...categories].map((c) => <option key={c}>{c}</option>)}
        </select></label>
        <label>Max price <input type="range" aria-label="Max price" min={0} max={top} value={maxPrice} onChange={(e) => setMaxPrice(Number(e.target.value))} /></label> ₹{maxPrice}
        <label>Min rating <select value={minRating} onChange={(e) => setMinRating(Number(e.target.value))}>
          {[0, 1, 2, 3, 4].map((r) => <option key={r} value={r}>{r}</option>)}
        </select></label>
        <label>Sort <select value={sort} onChange={(e) => setSort(e.target.value)}>
          <option value="none">Featured</option>
          <option value="price-asc">Price: low to high</option>
          <option value="price-desc">Price: high to low</option>
          <option value="rating-desc">Rating</option>
        </select></label>
      </aside>
      <p>{shown.length} results</p>
      {shown.length === 0 && <p>No products match</p>}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(160px, 1fr))', gap: 12 }}>
        {shown.map((p) => (
          <article key={p.id}>
            <h3>{p.title}</h3>
            <p>₹{p.price} · ★{p.rating}</p>
            <button aria-pressed={wish.has(p.id)} aria-label={(wish.has(p.id) ? 'Remove ' : 'Add ') + p.title + (wish.has(p.id) ? ' from wishlist' : ' to wishlist')}
              onClick={() => toggleWish(p.id)}>{wish.has(p.id) ? '♥' : '♡'}</button>
          </article>
        ))}
      </div>
    </div>
  )
}

