import WeatherApp from './weather-app/WeatherApp'

// Open-Meteo is free and needs no API key
async function fetchWeather(city) {
  const geo = await (await fetch('https://geocoding-api.open-meteo.com/v1/search?count=1&name=' + encodeURIComponent(city))).json()
  const place = geo.results?.[0]
  if (!place) throw new Error('not found')
  const url = 'https://api.open-meteo.com/v1/forecast?latitude=' + place.latitude + '&longitude=' + place.longitude +
    '&current=temperature_2m,apparent_temperature,relative_humidity_2m,wind_speed_10m,weather_code' +
    '&daily=temperature_2m_max,temperature_2m_min&timezone=auto'
  const w = await (await fetch(url)).json()
  return {
    city: place.name,
    current: { temp: w.current.temperature_2m, feelsLike: w.current.apparent_temperature, condition: 'Code ' + w.current.weather_code,
      humidity: w.current.relative_humidity_2m, wind: w.current.wind_speed_10m },
    daily: w.daily.time.map((d, i) => ({ day: new Date(d).toLocaleDateString('en', { weekday: 'short' }),
      min: w.daily.temperature_2m_min[i], max: w.daily.temperature_2m_max[i] })),
  }
}

