import { useEffect, useState } from 'react'

const loadSaved = () => { try { return JSON.parse(localStorage.getItem('weather')) ?? {} } catch { return {} } }

export default function WeatherApp({ fetchWeather }) {
  const saved = useState(loadSaved)[0]
  const [input, setInput] = useState(saved.city ?? '')
  const [unit, setUnit] = useState(saved.unit ?? 'C')
  const [data, setData] = useState(null)
  const [status, setStatus] = useState('idle')

  const search = async (city) => {
    const c = city.trim()
    if (!c) return
    setStatus('loading')
    try {
      const d = await fetchWeather(c)
      setData(d)
      setStatus('done')
      localStorage.setItem('weather', JSON.stringify({ city: c, unit }))
    } catch {
      setStatus('error')
    }
  }

  useEffect(() => { if (saved.city) search(saved.city) }, []) // eslint-disable-line react-hooks/exhaustive-deps

  const switchUnit = () => {
    const u = unit === 'C' ? 'F' : 'C'
    setUnit(u)
    const s = loadSaved()
    localStorage.setItem('weather', JSON.stringify({ ...s, unit: u }))
  }
  const t = (c) => (unit === 'C' ? Math.round(c) : Math.round((c * 9) / 5 + 32))

  return (
    <div className="weather">
      <input aria-label="City" value={input} onChange={(e) => setInput(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && search(input)} />
      <button onClick={() => search(input)}>Search</button>
      <button onClick={switchUnit}>Switch to °{unit === 'C' ? 'F' : 'C'}</button>
      {status === 'idle' && <p>Search for a city</p>}
      {status === 'loading' && <p>Loading…</p>}
      {status === 'error' && <p role="alert">City not found</p>}
      {status === 'done' && data && (
        <>
          <h2>{data.city}</h2>
          <p>{data.current.condition}</p>
          <p>Temperature: {t(data.current.temp)}°{unit}</p>
          <p>Feels like: {t(data.current.feelsLike)}°{unit}</p>
          <p>Humidity: {data.current.humidity}%</p>
          <p>Wind: {data.current.wind} km/h</p>
          <ul>{data.daily.slice(0, 5).map((d) => <li key={d.day}>{d.day} {t(d.max)}° / {t(d.min)}°</li>)}</ul>
        </>
      )}
    </div>
  )
}

