import { useEffect, useState } from 'react'

const randomShuffle = (a) => { const b = [...a]; for (let i = b.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [b[i], b[j]] = [b[j], b[i]] } return b }

export default function MemoryGame({ symbols = ['🍎', '🍌', '🍇', '🍒', '🥝', '🍑', '🍍', '🥥'], shuffle = randomShuffle }) {
  const deal = () => shuffle([...symbols, ...symbols])
  const [cards, setCards] = useState(deal)
  const [open, setOpen] = useState([])
  const [matched, setMatched] = useState(() => new Set())
  const [moves, setMoves] = useState(0)
  const [seconds, setSeconds] = useState(0)
  const [started, setStarted] = useState(false)
  const won = matched.size === symbols.length

  // mismatch: flip back after 800 ms
  useEffect(() => {
    if (open.length !== 2) return
    const [a, b] = open
    if (cards[a] === cards[b]) {
      setMatched((m) => new Set(m).add(cards[a]))
      setOpen([])
      return
    }
    const id = setTimeout(() => setOpen([]), 800)
    return () => clearTimeout(id)
  }, [open, cards])

  useEffect(() => {
    if (!started || won) return
    const id = setInterval(() => setSeconds((s) => s + 1), 1000)
    return () => clearInterval(id)
  }, [started, won])

  const flip = (i) => {
    if (open.length === 2 || open.includes(i) || matched.has(cards[i])) return
    setStarted(true)
    const next = [...open, i]
    setOpen(next)
    if (next.length === 2) setMoves((m) => m + 1)
  }

  const restart = () => {
    setCards(deal()); setOpen([]); setMatched(new Set()); setMoves(0); setSeconds(0); setStarted(false)
  }

  const cols = Math.ceil(Math.sqrt(cards.length))
  return (
    <div>
      <p>Moves: {moves} · Time: {seconds}s</p>
      {won && <p>You won in {moves} moves!</p>}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(' + cols + ', 64px)', gap: 6 }}>
        {cards.map((s, i) => {
          const up = open.includes(i) || matched.has(s)
          return <button key={i} aria-label={'Card ' + (i + 1)} disabled={matched.has(s)} onClick={() => flip(i)} style={{ height: 64, fontSize: 28 }}>{up ? s : '?'}</button>
        })}
      </div>
      <button onClick={restart}>Restart</button>
    </div>
  )
}

