import { useState } from 'react'

export default function Poll({ question, options, pollId, reveal = 'after-vote' }) {
  const key = 'poll-' + pollId
  const [choice, setChoice] = useState(() => localStorage.getItem(key))

  const counts = options.map((o) => o.votes + (String(o.id) === choice ? 1 : 0))
  const total = counts.reduce((a, b) => a + b, 0)
  const showResults = choice !== null || reveal === 'always'

  const vote = (id) => {
    if (choice !== null) return
    localStorage.setItem(key, String(id))
    setChoice(String(id))
  }

  return (
    <div className="poll">
      <h3>{question}</h3>
      <ul style={{ listStyle: 'none', padding: 0 }}>
        {options.map((o, i) => {
          const pct = total ? Math.round((counts[i] / total) * 100) : 0
          return (
            <li key={o.id}>
              <button disabled={choice !== null} aria-pressed={String(o.id) === choice} onClick={() => vote(o.id)}>{o.label}</button>
              {showResults && (
                <>
                  <span style={{ display: 'inline-block', width: 120, height: 8, background: '#eee', margin: '0 8px' }}>
                    <span style={{ display: 'block', width: pct + '%', height: '100%', background: '#1cb0f6' }} />
                  </span>
                  <span>{pct}%</span> <span>{counts[i]} votes</span>
                </>
              )}
            </li>
          )
        })}
      </ul>
      {showResults && <p>Total: {total} votes</p>}
    </div>
  )
}

