import { useEffect, useState } from 'react'

const CATEGORIES = ['Food', 'Travel', 'Bills', 'Other']
const blank = { description: '', amount: '', category: 'Food', date: '' }
const load = () => { try { return JSON.parse(localStorage.getItem('expenses')) ?? [] } catch { return [] } }

export default function ExpenseTracker() {
  const [expenses, setExpenses] = useState(load)
  const [form, setForm] = useState(blank)
  const [editingId, setEditingId] = useState(null)
  const [errors, setErrors] = useState({})
  const [month, setMonth] = useState('All')

  useEffect(() => { localStorage.setItem('expenses', JSON.stringify(expenses)) }, [expenses])

  const submit = (e) => {
    e.preventDefault()
    const errs = {}
    if (!form.description.trim()) errs.description = 'Description is required'
    if (!(Number(form.amount) > 0)) errs.amount = 'Amount must be more than 0'
    setErrors(errs)
    if (Object.keys(errs).length) return
    const item = { ...form, description: form.description.trim(), amount: Number(form.amount), date: form.date || new Date().toISOString().slice(0, 10) }
    if (editingId) setExpenses(expenses.map((x) => (x.id === editingId ? { ...item, id: editingId } : x)))
    else setExpenses([...expenses, { ...item, id: crypto.randomUUID() }])
    setForm(blank)
    setEditingId(null)
  }

  const months = [...new Set(expenses.map((x) => x.date.slice(0, 7)))].sort().reverse()
  const shown = expenses.filter((x) => month === 'All' || x.date.startsWith(month)).sort((a, b) => b.date.localeCompare(a.date))
  const total = shown.reduce((s, x) => s + x.amount, 0)
  const byCat = shown.reduce((acc, x) => ({ ...acc, [x.category]: (acc[x.category] ?? 0) + x.amount }), {})
  const field = (k) => ({ value: form[k], onChange: (e) => setForm({ ...form, [k]: e.target.value }) })

  return (
    <div>
      <form onSubmit={submit} noValidate>
        <label>Description <input {...field('description')} /></label>
        {errors.description && <span role="alert">{errors.description}</span>}
        <label>Amount <input type="number" {...field('amount')} /></label>
        {errors.amount && <span role="alert">{errors.amount}</span>}
        <label>Category <select {...field('category')}>{CATEGORIES.map((c) => <option key={c}>{c}</option>)}</select></label>
        <label>Date <input type="date" {...field('date')} /></label>
        <button type="submit">{editingId ? 'Save' : 'Add'}</button>
      </form>
      <label>Month <select value={month} onChange={(e) => setMonth(e.target.value)}>
        {['All', ...months].map((m) => <option key={m}>{m}</option>)}
      </select></label>
      <p>Total: ₹{total}</p>
      <ul aria-label="By category">
        {CATEGORIES.filter((c) => byCat[c]).map((c) => <li key={c}>{c}: ₹{byCat[c]}</li>)}
      </ul>
      <ul aria-label="Expenses">
        {shown.map((x) => (
          <li key={x.id}>
            {x.date} {x.description} ₹{x.amount} ({x.category})
            <button aria-label={'Edit ' + x.description} onClick={() => { setForm({ ...x, amount: String(x.amount) }); setEditingId(x.id) }}>Edit</button>
            <button aria-label={'Delete ' + x.description} onClick={() => setExpenses(expenses.filter((y) => y.id !== x.id))}>Delete</button>
          </li>
        ))}
      </ul>
    </div>
  )
}

