import { useEffect, useState } from 'react'

const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')

function inline(s) {
  const codes = []
  s = s.replace(/`([^`]+)`/g, (_, c) => { codes.push(c); return '\u0000' + (codes.length - 1) + '\u0000' })
  s = s.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>').replace(/\*(.+?)\*/g, '<em>$1</em>')
  s = s.replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, (_, text, url) =>
    /^(https?:\/\/|\/|#)/i.test(url) ? '<a href="' + url + '">' + text + '</a>' : text)
  return s.replace(/\u0000(\d+)\u0000/g, (_, i) => '<code>' + codes[i] + '</code>')
}

export function toHtml(md) {
  const lines = md.split('\n')
  const out = []
  let i = 0
  while (i < lines.length) {
    const line = lines[i]
    if (line.startsWith('```')) {
      const code = []
      i++
      while (i < lines.length && !lines[i].startsWith('```')) code.push(lines[i++])
      i++
      out.push('<pre><code>' + esc(code.join('\n')) + '</code></pre>')
    } else if (/^#{1,6}\s/.test(line)) {
      const n = line.match(/^#+/)[0].length
      out.push('<h' + n + '>' + inline(esc(line.slice(n).trim())) + '</h' + n + '>')
      i++
    } else if (/^[-*]\s/.test(line)) {
      const items = []
      while (i < lines.length && /^[-*]\s/.test(lines[i])) items.push('<li>' + inline(esc(lines[i++].slice(2).trim())) + '</li>')
      out.push('<ul>' + items.join('') + '</ul>')
    } else if (line.startsWith('>')) {
      const q = []
      while (i < lines.length && lines[i].startsWith('>')) q.push(lines[i++].replace(/^>\s?/, ''))
      out.push('<blockquote>' + inline(esc(q.join(' '))) + '</blockquote>')
    } else if (!line.trim()) {
      i++
    } else {
      const p = []
      while (i < lines.length && lines[i].trim() && !/^(#{1,6}\s|[-*]\s|>|```)/.test(lines[i])) p.push(lines[i++].trim())
      out.push('<p>' + inline(esc(p.join(' '))) + '</p>')
    }
  }
  return out.join('')
}

export default function MarkdownEditor({ initial = '# Hello\n\nType **markdown** here.' }) {
  const [text, setText] = useState(initial)
  const [html, setHtml] = useState(() => toHtml(initial))

  useEffect(() => {
    const id = setTimeout(() => setHtml(toHtml(text)), 200)
    return () => clearTimeout(id)
  }, [text])

  const words = text.trim() ? text.trim().split(/\s+/).length : 0
  return (
    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16 }}>
      <textarea aria-label="Markdown" rows={20} value={text} onChange={(e) => setText(e.target.value)} />
      <div data-testid="preview" className="preview" dangerouslySetInnerHTML={{ __html: html }} />
      <p>{text.length} characters · {words} words</p>
    </div>
  )
}

