import { useState } from 'react'

export default function SeatSelector({ rows = 5, cols = 8, taken = [], price = 200, max = 8, onBook }) {
  const [selected, setSelected] = useState(() => new Set())
  const [warn, setWarn] = useState('')
  const ids = []
  for (let r = 0; r < rows; r++) for (let c = 1; c <= cols; c++) ids.push(String.fromCharCode(65 + r) + c)
  const takenSet = new Set(taken)
  const chosen = ids.filter((id) => selected.has(id)) // grid order

  const toggle = (id) => {
    const n = new Set(selected)
    if (n.has(id)) { n.delete(id); setWarn('') }
    else if (n.size >= max) { setWarn('You can select up to ' + max + ' seats'); return }
    else n.add(id)
    setSelected(n)
  }
  const state = (id) => (takenSet.has(id) ? 'taken' : selected.has(id) ? 'selected' : 'available')

  return (
    <div className="seats">
      <p style={{ textAlign: 'center' }}>Screen</p>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(' + cols + ', 32px)', gap: 4 }}>
        {ids.map((id) => (
          <button key={id} aria-label={'Seat ' + id} data-state={state(id)} aria-pressed={selected.has(id)}
            disabled={takenSet.has(id)} onClick={() => toggle(id)}
            style={{ height: 28, background: { taken: '#999', selected: '#58cc02', available: '#fff' }[state(id)] }}>{id.slice(1)}</button>
        ))}
      </div>
      {warn && <p role="alert">{warn}</p>}
      <p>{chosen.length} seats selected · Total: ₹{chosen.length * price}</p>
      {chosen.length > 0 && <p>Seats: {chosen.join(', ')}</p>}
      <ul className="legend"><li>Available</li><li>Selected</li><li>Taken</li></ul>
      <button disabled={!chosen.length} onClick={() => onBook?.(chosen)}>Book</button>
    </div>
  )
}

