import { useEffect, useMemo, useState } from 'react'

const fmt = (s) => Math.floor(s / 60) + ':' + String(s % 60).padStart(2, '0')
const load = (tracks) => { try { return JSON.parse(localStorage.getItem('playlist')) ?? tracks } catch { return tracks } }

export default function Playlist({ tracks }) {
  const [list, setList] = useState(() => load(tracks))
  const [sortBy, setSortBy] = useState('none')
  const [desc, setDesc] = useState(false)
  const [query, setQuery] = useState('')
  const [playingId, setPlayingId] = useState(null)

  useEffect(() => { localStorage.setItem('playlist', JSON.stringify(list)) }, [list])

  const shown = useMemo(() => {
    const q = query.toLowerCase()
    const out = list.filter((t) => t.title.toLowerCase().includes(q) || t.artist.toLowerCase().includes(q))
    if (sortBy !== 'none') {
      out.sort((a, b) => (typeof a[sortBy] === 'number' ? a[sortBy] - b[sortBy] : a[sortBy].localeCompare(b[sortBy])))
      if (desc) out.reverse()
    }
    return out
  }, [list, sortBy, desc, query])

  const move = (id, d) => {
    const i = list.findIndex((t) => t.id === id)
    const j = i + d
    if (j < 0 || j >= list.length) return
    const next = [...list]
    ;[next[i], next[j]] = [next[j], next[i]]
    setList(next)
  }
  const playing = list.find((t) => t.id === playingId)
  const total = shown.reduce((s, t) => s + t.duration, 0)

  return (
    <div>
      <h2>{shown.length} tracks · {fmt(total)}</h2>
      <input aria-label="Search" value={query} onChange={(e) => setQuery(e.target.value)} />
      <label>Sort <select value={sortBy} onChange={(e) => setSortBy(e.target.value)}>
        {['none', 'title', 'artist', 'plays', 'duration'].map((k) => <option key={k} value={k}>{k}</option>)}
      </select></label>
      <label><input type="checkbox" checked={desc} onChange={(e) => setDesc(e.target.checked)} /> Descending</label>
      <ul aria-label="Tracks">
        {shown.map((t, i) => {
          const at = list.indexOf(t)
          return (
            <li key={t.id} aria-current={t.id === playingId ? 'true' : undefined} style={{ fontWeight: t.id === playingId ? 700 : 400 }}>
              {i + 1}. {t.title} — {t.artist} · {fmt(t.duration)} · {t.plays} plays
              <button aria-label={'Play ' + t.title} onClick={() => setPlayingId(t.id)}>▶</button>
              <button aria-label={'Move ' + t.title + ' up'} disabled={at === 0} onClick={() => move(t.id, -1)}>↑</button>
              <button aria-label={'Move ' + t.title + ' down'} disabled={at === list.length - 1} onClick={() => move(t.id, 1)}>↓</button>
              <button aria-label={'Remove ' + t.title} onClick={() => setList(list.filter((x) => x.id !== t.id))}>✕</button>
            </li>
          )
        })}
      </ul>
      {playing && <section aria-label="Now playing">{playing.title} — {playing.artist}</section>}
    </div>
  )
}

