import { useImperativeHandle, useRef, useState } from 'react'

// React 19: ref is a normal prop for function components
export default function VirtualList({ items, rowHeight, height, overscan = 3, renderItem, ref }) {
  const box = useRef(null)
  const [scrollTop, setScrollTop] = useState(0)

  useImperativeHandle(ref, () => ({
    scrollToIndex(i) {
      box.current.scrollTop = i * rowHeight
      setScrollTop(i * rowHeight)
    },
  }), [rowHeight])

  const first = Math.floor(scrollTop / rowHeight)
  const start = Math.max(0, first - overscan)
  const end = Math.min(items.length, first + Math.ceil(height / rowHeight) + overscan)

  const rows = []
  for (let i = start; i < end; i++) {
    rows.push(
      <div key={i} data-index={i} style={{ position: 'absolute', top: i * rowHeight + 'px', height: rowHeight, left: 0, right: 0 }}>
        {renderItem(items[i], i)}
      </div>,
    )
  }

  return (
    <div data-testid="viewport" ref={box} onScroll={(e) => setScrollTop(e.currentTarget.scrollTop)}
      style={{ height, overflowY: 'auto', position: 'relative' }}>
      <div data-testid="spacer" style={{ height: items.length * rowHeight + 'px', position: 'relative' }}>{rows}</div>
    </div>
  )
}

