import { useState } from 'react'

export function useForm({ initialValues, validate = {} }) {
  const [values, setValues] = useState(initialValues)
  const [touched, setTouched] = useState({})
  const [extra, setExtra] = useState({}) // errors set by hand (server)
  const [isSubmitting, setSubmitting] = useState(false)

  const check = (vals) => {
    const out = {}
    for (const [k, fn] of Object.entries(validate)) {
      const msg = fn(vals[k], vals)
      if (msg) out[k] = msg
    }
    return out
  }
  const all = { ...check(values), ...extra }
  const errors = Object.fromEntries(Object.entries(all).filter(([k]) => touched[k]))
  const isDirty = Object.keys(values).some((k) => values[k] !== initialValues[k])

  const register = (name) => ({
    name,
    value: values[name] ?? '',
    onChange: (e) => {
      setValues((v) => ({ ...v, [name]: e.target.value }))
      setExtra(({ [name]: _, ...rest }) => rest)
    },
    onBlur: () => setTouched((t) => ({ ...t, [name]: true })),
  })

  const handleSubmit = (fn) => async (e) => {
    e?.preventDefault?.()
    const errs = check(values)
    setTouched(Object.fromEntries([...Object.keys(values), ...Object.keys(validate)].map((k) => [k, true])))
    if (Object.keys(errs).length) return
    setSubmitting(true)
    try { await fn(values) } finally { setSubmitting(false) }
  }

  const setError = (name, message) => {
    setExtra((x) => ({ ...x, [name]: message }))
    setTouched((t) => ({ ...t, [name]: true }))
  }

  return { values, errors, touched, isDirty, isSubmitting, register, handleSubmit, setError, watch: (name) => values[name] }
}

