import { useCallback, useEffect, useReducer, useRef } from 'react'

const cache = new Map() // key → { data, error, updatedAt, promise, listeners }

export function clearCache() { cache.clear() }

function entry(key) {
  if (!cache.has(key)) cache.set(key, { data: undefined, error: null, updatedAt: 0, promise: null, listeners: new Set() })
  return cache.get(key)
}
const notify = (e) => e.listeners.forEach((l) => l())

function run(key, fn) {
  const e = entry(key)
  if (e.promise) return e.promise // dedupe
  e.promise = Promise.resolve()
    .then(fn)
    .then((data) => { e.data = data; e.error = null; e.updatedAt = Date.now() }, (err) => { e.error = err })
    .finally(() => { e.promise = null; notify(e) })
  notify(e)
  return e.promise
}

export function useQuery(key, fetchFn, { staleTime = 0, refetchOnWindowFocus = true } = {}) {
  const k = typeof key === 'string' ? key : JSON.stringify(key)
  const [, rerender] = useReducer((n) => n + 1, 0)
  const fnRef = useRef(fetchFn)
  fnRef.current = fetchFn

  const isStale = useCallback(() => {
    const e = entry(k)
    return e.updatedAt === 0 || Date.now() - e.updatedAt >= staleTime // staleTime 0 = stale at once
  }, [k, staleTime])

  useEffect(() => {
    const e = entry(k)
    e.listeners.add(rerender)
    if (isStale()) run(k, () => fnRef.current())
    return () => { e.listeners.delete(rerender) }
  }, [k, isStale])

  useEffect(() => {
    if (!refetchOnWindowFocus) return
    const onFocus = () => { if (isStale()) run(k, () => fnRef.current()) }
    window.addEventListener('focus', onFocus)
    return () => window.removeEventListener('focus', onFocus)
  }, [k, isStale, refetchOnWindowFocus])

  const e = entry(k)
  return {
    data: e.data,
    error: e.error,
    isFetching: !!e.promise,
    isLoading: !!e.promise && e.data === undefined,
    refetch: () => run(k, () => fnRef.current()),
  }
}

