import { Children, createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react'

const RouterCtx = createContext(null)
const RouteCtx = createContext({ base: '', params: {} })
const split = (p) => p.split('/').filter(Boolean)

export function BrowserRouter({ children }) {
  const [path, setPath] = useState(() => window.location.pathname)
  useEffect(() => {
    const onPop = () => setPath(window.location.pathname)
    window.addEventListener('popstate', onPop)
    return () => window.removeEventListener('popstate', onPop)
  }, [])
  const navigate = useCallback((to, { replace = false } = {}) => {
    window.history[replace ? 'replaceState' : 'pushState']({}, '', to)
    setPath(window.location.pathname)
  }, [])
  const value = useMemo(() => ({ path, navigate }), [path, navigate])
  return <RouterCtx.Provider value={value}>{children}</RouterCtx.Provider>
}

// returns { params, matched } or null
function match(pattern, path) {
  const pat = split(pattern)
  const segs = split(path)
  const params = {}
  for (let i = 0; i < pat.length; i++) {
    if (pat[i] === '*') return { params, matched: segs.slice(0, i) }
    if (i >= segs.length) return null
    if (pat[i].startsWith(':')) params[pat[i].slice(1)] = decodeURIComponent(segs[i])
    else if (pat[i] !== segs[i]) return null
  }
  return segs.length === pat.length ? { params, matched: segs } : null
}

export function Routes({ children }) {
  const { path } = useContext(RouterCtx)
  const parent = useContext(RouteCtx)
  const rest = path.startsWith(parent.base) ? path.slice(parent.base.length) : path
  for (const child of Children.toArray(children)) {
    const m = match(child.props.path, rest)
    if (m) {
      const base = parent.base + (m.matched.length ? '/' + m.matched.join('/') : '')
      return <RouteCtx.Provider value={{ base, params: { ...parent.params, ...m.params } }}>{child.props.element}</RouteCtx.Provider>
    }
  }
  return null
}

export function Route() { return null }

export function Link({ to, children, ...rest }) {
  const { navigate } = useContext(RouterCtx)
  const onClick = (e) => {
    if (e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey) return // let the browser open a new tab
    e.preventDefault()
    navigate(to)
  }
  return <a href={to} onClick={onClick} {...rest}>{children}</a>
}

export const useParams = () => useContext(RouteCtx).params
export const useNavigate = () => useContext(RouterCtx).navigate

