import { useEffect, useRef, useState } from 'react'

export default function SplitPanel({ direction = 'horizontal', initial = 50, min = 10, max = 90, storageKey, children }) {
  const [first, second] = children
  const box = useRef(null)
  const before = useRef(initial)
  const [size, setSize] = useState(() => {
    const saved = storageKey && Number(localStorage.getItem(storageKey))
    return saved || saved === 0 ? saved : initial
  })
  const vertical = direction === 'vertical'
  const clamp = (v) => Math.min(max, Math.max(min, v))

  useEffect(() => { if (storageKey) localStorage.setItem(storageKey, String(size)) }, [size, storageKey])

  const startDrag = (e) => {
    e.preventDefault()
    const onMove = (ev) => {
      const r = box.current.getBoundingClientRect()
      const pct = vertical ? ((ev.clientY - r.top) / r.height) * 100 : ((ev.clientX - r.left) / r.width) * 100
      setSize(clamp(pct))
    }
    const onUp = () => {
      document.removeEventListener('mousemove', onMove)
      document.removeEventListener('mouseup', onUp)
    }
    document.addEventListener('mousemove', onMove)
    document.addEventListener('mouseup', onUp)
  }

  const onKeyDown = (e) => {
    const less = vertical ? 'ArrowUp' : 'ArrowLeft'
    const more = vertical ? 'ArrowDown' : 'ArrowRight'
    if (e.key === less) { e.preventDefault(); setSize((s) => clamp(s - 5)) }
    if (e.key === more) { e.preventDefault(); setSize((s) => clamp(s + 5)) }
  }

  const toggleCollapse = () => {
    if (size === 0) setSize(before.current)
    else { before.current = size; setSize(0) }
  }

  return (
    <div data-testid="split" ref={box} style={{ display: 'flex', flexDirection: vertical ? 'column' : 'row', height: '100%' }}>
      <div data-testid="panel-1" style={{ flexBasis: size + '%', overflow: 'auto' }}>{first}</div>
      <div role="separator" tabIndex={0} aria-orientation={vertical ? 'horizontal' : 'vertical'}
        aria-valuenow={Math.round(size)} aria-valuemin={min} aria-valuemax={max}
        onMouseDown={startDrag} onKeyDown={onKeyDown} onDoubleClick={toggleCollapse}
        style={{ flex: '0 0 6px', background: '#ccc', cursor: vertical ? 'row-resize' : 'col-resize' }} />
      <div style={{ flex: 1, overflow: 'auto' }}>{second}</div>
    </div>
  )
}

