import { useSyncExternalStore } from 'react'

export function createStore(initialState, middlewares = []) {
  let state = initialState
  const listeners = new Set()

  const rawSet = (partial) => {
    const next = typeof partial === 'function' ? partial(state) : partial
    state = { ...state, ...next }
    listeners.forEach((l) => l())
  }
  // compose: middlewares[0] wraps middlewares[1] … wraps rawSet
  const set = middlewares.reduceRight((next, mw) => mw(next), rawSet)

  const getState = () => state
  const subscribe = (l) => { listeners.add(l); return () => listeners.delete(l) }

  function useStore(selector = (s) => s) {
    // re-renders only when the selected value changes (Object.is)
    return useSyncExternalStore(subscribe, () => selector(state))
  }
  useStore.getState = getState
  useStore.setState = (partial) => set(partial)
  useStore.subscribe = subscribe
  return useStore
}

