import { useCallback, useEffect, useReducer } from 'react'

function reducer(h, a) {
  switch (a.type) {
    case 'execute':
      return { state: a.cmd.execute(h.state), past: [...h.past, a.cmd].slice(-a.max), future: [] }
    case 'undo': {
      if (!h.past.length) return h
      const cmd = h.past[h.past.length - 1]
      return { state: cmd.undo(h.state), past: h.past.slice(0, -1), future: [cmd, ...h.future] }
    }
    case 'redo': {
      if (!h.future.length) return h
      const [cmd, ...rest] = h.future
      return { state: cmd.execute(h.state), past: [...h.past, cmd], future: rest }
    }
    default:
      return h
  }
}

export function useHistory(initialState, { max = 50, keyboard = true } = {}) {
  const [h, dispatch] = useReducer(reducer, { state: initialState, past: [], future: [] })
  const execute = useCallback((cmd) => dispatch({ type: 'execute', cmd, max }), [max])
  const undo = useCallback(() => dispatch({ type: 'undo' }), [])
  const redo = useCallback(() => dispatch({ type: 'redo' }), [])

  useEffect(() => {
    if (!keyboard) return
    const onKey = (e) => {
      if (!(e.ctrlKey || e.metaKey)) return
      const k = e.key.toLowerCase()
      if (k === 'z' && !e.shiftKey) { e.preventDefault(); undo() }
      else if (k === 'y' || (k === 'z' && e.shiftKey)) { e.preventDefault(); redo() }
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [keyboard, undo, redo])

  return { state: h.state, execute, undo, redo, canUndo: h.past.length > 0, canRedo: h.future.length > 0 }
}

