import { useState } from 'react'

export default function FileExplorer({ root, loadChildren }) {
  const [kids, setKids] = useState({}) // folderId → children
  const [status, setStatus] = useState({}) // folderId → 'loading' | 'error'
  const [open, setOpen] = useState(() => new Set())
  const [selected, setSelected] = useState(null)

  const load = async (id) => {
    setStatus((s) => ({ ...s, [id]: 'loading' }))
    try {
      const list = await loadChildren(id)
      setKids((k) => ({ ...k, [id]: list }))
      setStatus(({ [id]: _, ...s }) => s)
    } catch {
      setStatus((s) => ({ ...s, [id]: 'error' }))
    }
  }
  const setOpenTo = (node, value) => {
    if (node.type !== 'folder') return
    const n = new Set(open)
    if (value) { n.add(node.id); if (!kids[node.id] && status[node.id] !== 'loading') load(node.id) } else n.delete(node.id)
    setOpen(n)
  }

  // visible nodes in screen order, with their path
  const visible = []
  const walk = (nodes, path) => nodes.forEach((n) => {
    const p = [...path, n.name]
    visible.push({ node: n, path: p })
    if (open.has(n.id) && kids[n.id]) walk(kids[n.id], p)
  })
  walk(root, [])
  const current = visible.find((v) => v.node.id === selected)

  const onKeyDown = (e) => {
    const i = visible.findIndex((v) => v.node.id === selected)
    const node = visible[i]?.node
    if (e.key === 'ArrowDown') { e.preventDefault(); setSelected(visible[Math.min(i + 1, visible.length - 1)].node.id) }
    if (e.key === 'ArrowUp') { e.preventDefault(); setSelected(visible[Math.max(i - 1, 0)].node.id) }
    if (!node) return
    if (e.key === 'ArrowRight') setOpenTo(node, true)
    if (e.key === 'ArrowLeft') setOpenTo(node, false)
    if (e.key === 'Enter') setOpenTo(node, !open.has(node.id))
  }

  const render = (nodes) => nodes.map((n) => {
    const isOpen = open.has(n.id)
    return (
      <li key={n.id} role="treeitem" aria-label={n.name} aria-selected={selected === n.id}
        aria-expanded={n.type === 'folder' ? isOpen : undefined}
        onClick={(e) => { e.stopPropagation(); setSelected(n.id); setOpenTo(n, !isOpen) }}>
        <span style={{ background: selected === n.id ? '#ddf4ff' : undefined }}>
          {n.type === 'folder' ? (isOpen ? '▾ 📁 ' : '▸ 📁 ') : '📄 '}{n.name}
        </span>
        {isOpen && (
          <ul role="group" style={{ paddingLeft: 16 }}>
            {status[n.id] === 'loading' && <li>Loading…</li>}
            {status[n.id] === 'error' && <li>Failed to load <button onClick={(e) => { e.stopPropagation(); load(n.id) }}>Retry</button></li>}
            {kids[n.id] && render(kids[n.id])}
          </ul>
        )}
      </li>
    )
  })

  return (
    <div>
      <nav aria-label="Breadcrumb">{current ? current.path.join(' / ') : ''}</nav>
      <ul role="tree" tabIndex={0} onKeyDown={onKeyDown} style={{ listStyle: 'none', paddingLeft: 0 }}>{render(root)}</ul>
    </div>
  )
}

