import { useState } from 'react'

let nextId = 1
const updateNode = (list, id, fn) => list.map((c) => (c.id === id ? fn(c) : { ...c, replies: updateNode(c.replies, id, fn) }))
const removeNode = (list, id) => list.filter((c) => c.id !== id).map((c) => ({ ...c, replies: removeNode(c.replies, id) }))
const make = (text) => ({ id: 'n' + nextId++, text, likes: 0, replies: [] })

function Comment({ c, api }) {
  const [mode, setMode] = useState(null) // 'reply' | 'edit'
  const [draft, setDraft] = useState('')
  const liked = api.liked.has(c.id)
  const hidden = api.collapsed.has(c.id)
  return (
    <li>
      <article>
        <p>{c.text}</p>
        <span>{c.likes + (liked ? 1 : 0)} likes</span>
        <button aria-pressed={liked} onClick={() => api.toggle('liked', c.id)}>Like</button>
        <button onClick={() => { setMode('reply'); setDraft('') }}>Reply</button>
        <button onClick={() => { setMode('edit'); setDraft(c.text) }}>Edit</button>
        <button onClick={() => window.confirm('Delete this comment and its replies?') && api.remove(c.id)}>Delete</button>
        {c.replies.length > 0 && <button onClick={() => api.toggle('collapsed', c.id)}>{hidden ? 'Expand' : 'Collapse'}</button>}
        {mode && (
          <div>
            <textarea aria-label={mode === 'reply' ? 'Reply' : 'Edit comment'} value={draft} onChange={(e) => setDraft(e.target.value)} />
            <button onClick={() => {
              if (!draft.trim()) return
              mode === 'reply' ? api.reply(c.id, draft.trim()) : api.edit(c.id, draft.trim())
              setMode(null)
            }}>{mode === 'reply' ? 'Send' : 'Save'}</button>
          </div>
        )}
      </article>
      {!hidden && c.replies.length > 0 && <ul>{c.replies.map((r) => <Comment key={r.id} c={r} api={api} />)}</ul>}
    </li>
  )
}

export default function CommentSection({ initial = [] }) {
  const [tree, setTree] = useState(initial)
  const [liked, setLiked] = useState(() => new Set())
  const [collapsed, setCollapsed] = useState(() => new Set())
  const [text, setText] = useState('')

  const api = {
    liked, collapsed,
    toggle: (which, id) => {
      const [set, setter] = which === 'liked' ? [liked, setLiked] : [collapsed, setCollapsed]
      const n = new Set(set); n.has(id) ? n.delete(id) : n.add(id); setter(n)
    },
    reply: (id, t) => setTree((tr) => updateNode(tr, id, (c) => ({ ...c, replies: [...c.replies, make(t)] }))),
    edit: (id, t) => setTree((tr) => updateNode(tr, id, (c) => ({ ...c, text: t }))),
    remove: (id) => setTree((tr) => removeNode(tr, id)),
  }

  return (
    <section>
      <textarea aria-label="Add a comment" value={text} onChange={(e) => setText(e.target.value)} />
      <button onClick={() => { if (text.trim()) { setTree([...tree, make(text.trim())]); setText('') } }}>Post</button>
      <ul>{tree.map((c) => <Comment key={c.id} c={c} api={api} />)}</ul>
    </section>
  )
}

