import { act, fireEvent, render, screen, within } from '@testing-library/react'
import ChatApp from './ChatApp'

const contacts = [{ id: 'asha', name: 'Asha' }, { id: 'bilal', name: 'Bilal' }]
const replies = ['Hey!', 'Cool', 'See you']
beforeEach(() => {
  vi.useFakeTimers()
  Element.prototype.scrollIntoView = vi.fn()
})
afterEach(() => vi.useRealTimers())

const wait = (ms) => act(() => vi.advanceTimersByTime(ms))
const box = () => screen.getByLabelText('Message')
const send = (t) => {
  fireEvent.change(box(), { target: { value: t } })
  fireEvent.keyDown(box(), { key: 'Enter' })
}
const msgs = () => within(screen.getByRole('list', { name: 'Messages' })).queryAllByRole('listitem')
  .filter((li) => li.dataset.from).map((li) => li.dataset.from + ':' + li.querySelector('span').textContent)
const setup = () => render(<ChatApp contacts={contacts} replies={replies} replyDelay={1000} />)

test('opens the first contact', () => {
  setup()
  expect(screen.getByRole('heading', { name: 'Asha' })).toBeTruthy()
  expect(msgs()).toEqual([])
})

test('Enter sends; blank and Shift+Enter do not', () => {
  setup()
  send('   ')
  fireEvent.change(box(), { target: { value: 'Hi' } })
  fireEvent.keyDown(box(), { key: 'Enter', shiftKey: true })
  expect(msgs()).toEqual([])
  send('Hi there')
  expect(msgs()).toEqual(['me:Hi there'])
  expect(box().value).toBe('')
  expect(screen.getByRole('list', { name: 'Messages' }).textContent).toContain('✓')
})

test('typing… then a reply, and ✓✓ on my message', () => {
  setup()
  send('Hi')
  expect(screen.getByText('typing…')).toBeTruthy()
  wait(1000)
  expect(screen.queryByText('typing…')).toBeNull()
  expect(msgs()).toEqual(['me:Hi', 'them:Hey!'])
  expect(screen.getByRole('list', { name: 'Messages' }).textContent).toContain('✓✓')
})

test('replies go through the list in order', () => {
  setup()
  for (const t of ['1', '2', '3', '4']) { send(t); wait(1000) }
  expect(msgs().filter((m) => m.startsWith('them'))).toEqual(['them:Hey!', 'them:Cool', 'them:See you', 'them:Hey!'])
})

test('each contact has its own conversation', () => {
  setup()
  send('For Asha')
  wait(1000)
  fireEvent.click(screen.getByRole('button', { name: 'Bilal' }))
  expect(screen.getByRole('heading', { name: 'Bilal' })).toBeTruthy()
  expect(msgs()).toEqual([])
  fireEvent.click(screen.getByRole('button', { name: 'Asha' }))
  expect(msgs()[0]).toBe('me:For Asha')
})

test('a reply in another chat adds an unread badge; opening clears it', () => {
  setup()
  send('Hi Asha')
  fireEvent.click(screen.getByRole('button', { name: 'Bilal' }))
  wait(1000)
  expect(screen.getByTestId('unread-asha').textContent).toBe('1')
  expect(msgs()).toEqual([])
  fireEvent.click(screen.getByRole('button', { name: 'Asha' }))
  expect(screen.queryByTestId('unread-asha')).toBeNull()
  expect(msgs()).toEqual(['me:Hi Asha', 'them:Hey!'])
})

test('scrolls to the newest message', () => {
  setup()
  Element.prototype.scrollIntoView.mockClear()
  send('Hi')
  expect(Element.prototype.scrollIntoView).toHaveBeenCalled()
})

