import { useEffect, useRef, useState } from 'react'

const now = () => new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })

export default function ChatApp({ contacts, replies, replyDelay = 1500 }) {
  const [activeId, setActiveId] = useState(contacts[0]?.id)
  const [messages, setMessages] = useState({})
  const [typing, setTyping] = useState(() => new Set())
  const [unread, setUnread] = useState({})
  const [text, setText] = useState('')
  const nextReply = useRef(0)
  const timers = useRef(new Set())
  const activeRef = useRef(activeId)
  activeRef.current = activeId
  const end = useRef(null)

  useEffect(() => () => timers.current.forEach(clearTimeout), [])
  const list = messages[activeId] ?? []
  useEffect(() => { end.current?.scrollIntoView?.({ behavior: 'smooth' }) }, [list.length, activeId])

  const add = (id, msg) => setMessages((m) => ({ ...m, [id]: [...(m[id] ?? []), msg] }))

  const send = () => {
    const t = text.trim()
    if (!t) return
    const id = activeId // captured for the timer
    add(id, { from: 'me', text: t, time: now(), read: false })
    setText('')
    setTyping((s) => new Set(s).add(id))
    const timer = setTimeout(() => {
      timers.current.delete(timer)
      const reply = replies[nextReply.current++ % replies.length]
      setMessages((m) => ({
        ...m,
        [id]: [...(m[id] ?? []).map((x) => (x.from === 'me' ? { ...x, read: true } : x)), { from: 'them', text: reply, time: now() }],
      }))
      setTyping((s) => { const n = new Set(s); n.delete(id); return n })
      if (activeRef.current !== id) setUnread((u) => ({ ...u, [id]: (u[id] ?? 0) + 1 }))
    }, replyDelay)
    timers.current.add(timer)
  }

  const open = (id) => { setActiveId(id); setUnread((u) => ({ ...u, [id]: 0 })) }
  const contact = contacts.find((c) => c.id === activeId)

  return (
    <div style={{ display: 'flex', gap: 16 }}>
      <ul aria-label="Contacts" style={{ listStyle: 'none', padding: 0 }}>
        {contacts.map((c) => (
          <li key={c.id}>
            <button aria-label={c.name} onClick={() => open(c.id)} style={{ fontWeight: c.id === activeId ? 700 : 400 }}>
              {c.name} {unread[c.id] > 0 && <span data-testid={'unread-' + c.id}>{unread[c.id]}</span>}
            </button>
          </li>
        ))}
      </ul>
      <section style={{ flex: 1 }}>
        <h2>{contact?.name}</h2>
        <ul aria-label="Messages" style={{ listStyle: 'none', padding: 0, maxHeight: 400, overflowY: 'auto' }}>
          {list.map((m, i) => (
            <li key={i} data-from={m.from} style={{ textAlign: m.from === 'me' ? 'right' : 'left' }}>
              <span>{m.text}</span> <small>{m.time}</small> {m.from === 'me' && <small>{m.read ? '✓✓' : '✓'}</small>}
            </li>
          ))}
          <li ref={end} aria-hidden="true" />
        </ul>
        {typing.has(activeId) && <p>typing…</p>}
        <textarea aria-label="Message" value={text} onChange={(e) => setText(e.target.value)}
          onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); send() } }} />
      </section>
    </div>
  )
}

