import { useEffect, useState } from 'react'

function randomMines(rows, cols, count, safe) {
  const out = new Set()
  while (out.size < count) {
    const i = Math.floor(Math.random() * rows * cols)
    if (i !== safe) out.add(i)
  }
  return [...out]
}

export default function Minesweeper({ rows = 9, cols = 9, mines = 10, placeMines = randomMines }) {
  const [mineSet, setMineSet] = useState(null)
  const [revealed, setRevealed] = useState(() => new Set())
  const [flagged, setFlagged] = useState(() => new Set())
  const [status, setStatus] = useState('Playing')
  const [seconds, setSeconds] = useState(0)
  const total = rows * cols

  const neighbours = (i) => {
    const r = Math.floor(i / cols), c = i % cols, out = []
    for (let dr = -1; dr <= 1; dr++) for (let dc = -1; dc <= 1; dc++) {
      const nr = r + dr, nc = c + dc
      if ((dr || dc) && nr >= 0 && nr < rows && nc >= 0 && nc < cols) out.push(nr * cols + nc)
    }
    return out
  }
  const count = (set, i) => neighbours(i).filter((n) => set.has(n)).length

  useEffect(() => {
    if (!mineSet || status !== 'Playing') return
    const id = setInterval(() => setSeconds((s) => s + 1), 1000)
    return () => clearInterval(id)
  }, [mineSet, status])

  const reveal = (i) => {
    if (status !== 'Playing' || flagged.has(i) || revealed.has(i)) return
    const set = mineSet ?? new Set(placeMines(rows, cols, mines, i))
    if (!mineSet) setMineSet(set)
    if (set.has(i)) {
      setRevealed(new Set([...revealed, ...set]))
      setStatus('Game over')
      return
    }
    const next = new Set(revealed)
    const queue = [i]
    while (queue.length) {
      const k = queue.shift()
      if (next.has(k) || flagged.has(k)) continue
      next.add(k)
      if (count(set, k) === 0) queue.push(...neighbours(k).filter((n) => !next.has(n)))
    }
    setRevealed(next)
    if (next.size === total - set.size) setStatus('You win!')
  }

  const flag = (e, i) => {
    e.preventDefault()
    if (status !== 'Playing' || revealed.has(i)) return
    const n = new Set(flagged)
    n.has(i) ? n.delete(i) : n.add(i)
    setFlagged(n)
  }

  const restart = () => { setMineSet(null); setRevealed(new Set()); setFlagged(new Set()); setStatus('Playing'); setSeconds(0) }

  return (
    <div>
      <p>Mines left: {mines - flagged.size} · Time: {seconds}</p>
      <p role="status">{status}</p>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(' + cols + ', 28px)', gap: 2 }}>
        {Array.from({ length: total }, (_, i) => {
          const open = revealed.has(i)
          const state = open ? 'revealed' : flagged.has(i) ? 'flagged' : 'hidden'
          const label = open ? (mineSet.has(i) ? '💣' : count(mineSet, i) || '') : flagged.has(i) ? '🚩' : ''
          return (
            <button key={i} aria-label={'Cell ' + (Math.floor(i / cols) + 1) + '-' + ((i % cols) + 1)} data-state={state}
              onClick={() => reveal(i)} onContextMenu={(e) => flag(e, i)}
              style={{ height: 28, background: open ? '#eee' : '#bbb' }}>{label}</button>
          )
        })}
      </div>
      <button onClick={restart}>Restart</button>
    </div>
  )
}

