import { useEffect, useReducer } from 'react'

const DIRS = { up: [0, -1], down: [0, 1], left: [-1, 0], right: [1, 0] }
const OPPOSITE = { up: 'down', down: 'up', left: 'right', right: 'left' }
const KEYS = { ArrowUp: 'up', ArrowDown: 'down', ArrowLeft: 'left', ArrowRight: 'right', w: 'up', s: 'down', a: 'left', d: 'right' }
const START = [{ x: 2, y: 5 }, { x: 1, y: 5 }, { x: 0, y: 5 }]
const randomFood = (free) => free[Math.floor(Math.random() * free.length)]
const same = (a, b) => a.x === b.x && a.y === b.y

function freeCells(size, snake) {
  const out = []
  for (let y = 0; y < size; y++) for (let x = 0; x < size; x++) if (!snake.some((s) => s.x === x && s.y === y)) out.push({ x, y })
  return out
}

function init({ size, nextFood, initialSnake, initialDir }) {
  const snake = initialSnake ?? START
  return { snake, dir: initialDir, nextDir: initialDir, food: nextFood(freeCells(size, snake)), score: 0, running: false, over: false }
}

function reducer(s, a) {
  switch (a.type) {
    case 'start': return { ...s, running: true }
    case 'turn': return OPPOSITE[a.dir] === s.dir ? s : { ...s, nextDir: a.dir }
    case 'restart': return init(a.cfg)
    case 'tick': {
      if (!s.running || s.over) return s
      const [dx, dy] = DIRS[s.nextDir]
      const head = { x: s.snake[0].x + dx, y: s.snake[0].y + dy }
      const eats = same(head, s.food)
      const body = eats ? s.snake : s.snake.slice(0, -1) // the tail moves away unless we grow
      const hitWall = head.x < 0 || head.y < 0 || head.x >= a.size || head.y >= a.size
      if (hitWall || body.some((p) => same(p, head))) return { ...s, over: true, running: false }
      const snake = [head, ...body]
      return { ...s, snake, dir: s.nextDir, score: s.score + (eats ? 1 : 0), food: eats ? a.nextFood(freeCells(a.size, snake)) : s.food }
    }
    default: return s
  }
}

export default function SnakeGame({ size = 10, speed = 200, nextFood = randomFood, initialSnake, initialDir = 'right' }) {
  const cfg = { size, nextFood, initialSnake, initialDir }
  const [s, dispatch] = useReducer(reducer, cfg, init)
  const high = Math.max(s.score, Number(localStorage.getItem('snake-high') ?? 0))

  useEffect(() => {
    if (!s.running) return
    const id = setInterval(() => dispatch({ type: 'tick', size, nextFood }), Math.max(60, speed - s.score * 10))
    return () => clearInterval(id)
  }, [s.running, s.score, speed, size, nextFood])

  useEffect(() => {
    const onKey = (e) => {
      const dir = KEYS[e.key] ?? KEYS[e.key.toLowerCase?.()]
      if (dir) { e.preventDefault(); dispatch({ type: 'turn', dir }) }
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [])

  useEffect(() => { if (s.over) localStorage.setItem('snake-high', String(high)) }, [s.over, high])

  const cells = []
  for (let y = 0; y < size; y++) for (let x = 0; x < size; x++) {
    const type = s.snake.some((p) => p.x === x && p.y === y) ? 'snake' : same(s.food, { x, y }) ? 'food' : 'empty'
    cells.push(<div key={x + '-' + y} data-x={x} data-y={y} data-type={type}
      style={{ width: 20, height: 20, background: type === 'snake' ? '#58cc02' : type === 'food' ? '#ff4b4b' : '#f4f4f4' }} />)
  }

  return (
    <div>
      <p>Score: {s.score} · High score: {high}</p>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(' + size + ', 20px)', gap: 1 }}>{cells}</div>
      {!s.running && !s.over && <button onClick={() => dispatch({ type: 'start' })}>Start</button>}
      {s.over && <div><p>Game over</p><button onClick={() => dispatch({ type: 'restart', cfg })}>Restart</button></div>}
    </div>
  )
}

