  return <div>calendar</div>
}

import DateRangePicker from './date-picker/DateRangePicker'

export default function App() {
  return <DateRangePicker min="2026-01-01" onChange={(r) => console.log(r)} />
}

import { render, screen } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import DateRangePicker from './DateRangePicker'

const today = new Date(2026, 9, 25) // 25 Oct 2026
const day = (d) => screen.getByRole('button', { name: d })
const has = (d, attr) => day(d).hasAttribute(attr)
const btn = (name) => screen.getByRole('button', { name })

test('draws the month with the right first weekday', () => {
  render(<DateRangePicker today={today} />)
  expect(screen.getByRole('heading', { name: 'October 2026' })).toBeTruthy()
  expect(document.querySelectorAll('[data-blank]')).toHaveLength(4) // 1 Oct 2026 is a Thursday
  expect(screen.getAllByRole('button', { name: /^2026-10-/ })).toHaveLength(31)
  expect(has('2026-10-25', 'data-today')).toBe(true)
  expect(day('2026-10-01').textContent).toBe('1')
})

test('previous / next month and Today', async () => {
  const user = userEvent.setup()
  render(<DateRangePicker today={today} />)
  await user.click(btn('Previous month'))
  expect(screen.getByRole('heading', { name: 'September 2026' })).toBeTruthy()
  expect(document.querySelectorAll('[data-blank]')).toHaveLength(2)
  expect(screen.getAllByRole('button', { name: /^2026-09-/ })).toHaveLength(30)
  await user.click(btn('Next month'))
  await user.click(btn('Next month'))
  await user.click(btn('Next month'))
  expect(screen.getByRole('heading', { name: 'December 2026' })).toBeTruthy()
  await user.click(btn('Next month'))
  expect(screen.getByRole('heading', { name: 'January 2027' })).toBeTruthy()
  await user.click(btn('Today'))
  expect(screen.getByRole('heading', { name: 'October 2026' })).toBeTruthy()
})

test('two clicks make a range and call onChange', async () => {
  const user = userEvent.setup()
  const onChange = vi.fn()
  render(<DateRangePicker today={today} onChange={onChange} />)
  await user.click(day('2026-10-05'))
  expect(has('2026-10-05', 'data-start')).toBe(true)
  expect(onChange).not.toHaveBeenCalled()
  await user.click(day('2026-10-09'))
  expect(onChange).toHaveBeenCalledWith({ start: '2026-10-05', end: '2026-10-09' })
  expect(has('2026-10-09', 'data-end')).toBe(true)
  expect(has('2026-10-07', 'data-in-range')).toBe(true)
  expect(has('2026-10-10', 'data-in-range')).toBe(false)
})

test('an earlier second click swaps; a third click starts again', async () => {
  const user = userEvent.setup()
  const onChange = vi.fn()
  render(<DateRangePicker today={today} onChange={onChange} />)
  await user.click(day('2026-10-20'))
  await user.click(day('2026-10-12'))
  expect(onChange).toHaveBeenLastCalledWith({ start: '2026-10-12', end: '2026-10-20' })
  await user.click(day('2026-10-02'))
  expect(has('2026-10-02', 'data-start')).toBe(true)
  expect(has('2026-10-15', 'data-in-range')).toBe(false)
})

test('hover previews the range', async () => {
  const user = userEvent.setup()
  render(<DateRangePicker today={today} />)
  await user.click(day('2026-10-05'))
  await user.hover(day('2026-10-08'))
  expect(has('2026-10-07', 'data-in-range')).toBe(true)
  expect(has('2026-10-09', 'data-in-range')).toBe(false)
})

test('min and max disable days', () => {
  render(<DateRangePicker today={today} min="2026-10-10" max="2026-10-20" />)
  expect(day('2026-10-09').disabled).toBe(true)
  expect(day('2026-10-10').disabled).toBe(false)
  expect(day('2026-10-21').disabled).toBe(true)
})

test('presets', async () => {
  const user = userEvent.setup()
  const onChange = vi.fn()
  render(<DateRangePicker today={today} onChange={onChange} />)
  await user.click(btn('Last 7 days'))
