import { useState } from 'react'

const pad = (n) => String(n).padStart(2, '0')
const iso = (y, m, d) => y + '-' + pad(m + 1) + '-' + pad(d)
const isoOf = (date) => iso(date.getFullYear(), date.getMonth(), date.getDate())
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']

export default function DateRangePicker({ today = new Date(), min, max, onChange }) {
  const todayIso = isoOf(today)
  const [view, setView] = useState({ y: today.getFullYear(), m: today.getMonth() })
  const [start, setStart] = useState(null)
  const [end, setEnd] = useState(null)
  const [hover, setHover] = useState(null)

  const shift = (d) => setView(({ y, m }) => ({ y: m + d < 0 ? y - 1 : m + d > 11 ? y + 1 : y, m: (m + d + 12) % 12 }))
  const setRange = (a, b) => { const [s, e] = a <= b ? [a, b] : [b, a]; setStart(s); setEnd(e); onChange?.({ start: s, end: e }) }

  const pick = (day) => {
    if (!start || end) { setStart(day); setEnd(null); return }
    setRange(start, day)
  }

  const lastEnd = end ?? (start && hover ? hover : null)
  const [lo, hi] = start && lastEnd ? (start <= lastEnd ? [start, lastEnd] : [lastEnd, start]) : [null, null]

  const first = new Date(view.y, view.m, 1).getDay()
  const days = new Date(view.y, view.m + 1, 0).getDate()
  const back = (n) => { const d = new Date(today); d.setDate(d.getDate() - n); return isoOf(d) }

  return (
    <div className="picker">
      <button onClick={() => shift(-1)}>Previous month</button>
      <h3 style={{ display: 'inline-block', margin: '0 8px' }}>{MONTHS[view.m]} {view.y}</h3>
      <button onClick={() => shift(1)}>Next month</button>
      <button onClick={() => setView({ y: today.getFullYear(), m: today.getMonth() })}>Today</button>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 36px)', gap: 2 }} onMouseLeave={() => setHover(null)}>
        {['Su', 'Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa'].map((w) => <b key={w}>{w}</b>)}
        {Array.from({ length: first }, (_, i) => <span key={'b' + i} data-blank="" />)}
        {Array.from({ length: days }, (_, i) => {
          const day = iso(view.y, view.m, i + 1)
          const off = (min && day < min) || (max && day > max)
          return (
            <button key={day} aria-label={day} disabled={!!off}
              data-today={day === todayIso ? '' : undefined}
              data-start={day === start ? '' : undefined}
              data-end={day === end ? '' : undefined}
              data-in-range={lo && day >= lo && day <= hi ? '' : undefined}
              onClick={() => pick(day)} onMouseEnter={() => setHover(day)}
              style={{ background: lo && day >= lo && day <= hi ? '#ddf4ff' : undefined, fontWeight: day === todayIso ? 700 : 400 }}>
              {i + 1}
            </button>
          )
        })}
      </div>
      <button onClick={() => setRange(back(6), todayIso)}>Last 7 days</button>
      <button onClick={() => setRange(iso(today.getFullYear(), today.getMonth(), 1), iso(today.getFullYear(), today.getMonth(), new Date(today.getFullYear(), today.getMonth() + 1, 0).getDate()))}>This month</button>
    </div>
  )
}

