import { createContext, useContext, useEffect, useState } from 'react'

const AuthCtx = createContext(null)
export const useAuth = () => useContext(AuthCtx)

export function AuthProvider({ api, children }) {
  const [user, setUser] = useState(null)
  const [checking, setChecking] = useState(() => !!localStorage.getItem('token'))

  useEffect(() => {
    const token = localStorage.getItem('token')
    if (!token) return
    api.me(token).then(setUser, () => localStorage.removeItem('token')).finally(() => setChecking(false))
  }, [api])

  const login = async (email, password) => {
    const { token, user } = await api.login(email, password)
    localStorage.setItem('token', token)
    setUser(user)
  }
  const logout = () => { localStorage.removeItem('token'); setUser(null) }
  return <AuthCtx.Provider value={{ user, checking, login, logout }}>{children}</AuthCtx.Provider>
}

const NavCtx = createContext(null)
function useNav() { return useContext(NavCtx) }

export function ProtectedRoute({ children }) {
  const { user } = useAuth()
  const { path, go } = useNav()
  useEffect(() => { if (!user) go('/login', { from: path, replace: true }) }, [user, path, go])
  return user ? children : null
}

function Home() {
  const { user } = useAuth()
  return <p>{user ? 'Welcome, ' + user.name : 'You are not logged in'}</p>
}

function Login() {
  const { login } = useAuth()
  const { from, go } = useNav()
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [errors, setErrors] = useState({})
  const [busy, setBusy] = useState(false)

  const submit = async (e) => {
    e.preventDefault()
    const errs = {}
    if (!/^\S+@\S+\.\S+$/.test(email)) errs.email = 'Enter a valid email'
    if (!password) errs.password = 'Password is required'
    setErrors(errs)
    if (Object.keys(errs).length) return
    setBusy(true)
    try {
      await login(email, password)
      go(from || '/')
    } catch (err) {
      setErrors({ api: err.message })
      setBusy(false)
    }
  }

  return (
    <form onSubmit={submit} noValidate>
      {from && <p>Please log in to continue</p>}
      <label>Email <input value={email} onChange={(e) => setEmail(e.target.value)} /></label>
      {errors.email && <span>{errors.email}</span>}
      <label>Password <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} /></label>
      {errors.password && <span>{errors.password}</span>}
      {errors.api && <p role="alert">{errors.api}</p>}
      <button disabled={busy}>{busy ? 'Logging in…' : 'Log in'}</button>
    </form>
  )
}

function Profile() {
  const { user, logout } = useAuth()
  const { go } = useNav()
  return (
    <section>
      <h2>Profile</h2>
      <p>Signed in as {user.name}</p>
      <button onClick={() => { logout(); go('/') }}>Log out</button>
    </section>
  )
}

function Pages() {
  const { checking } = useAuth()
  const [path, setPath] = useState(() => window.location.pathname)
  const [from, setFrom] = useState(null)
  useEffect(() => {
    const onPop = () => setPath(window.location.pathname)
    window.addEventListener('popstate', onPop)
    return () => window.removeEventListener('popstate', onPop)
  }, [])
  const [nav] = useState(() => ({}))
  nav.path = path
  nav.from = from
  nav.go = nav.go ?? ((to, opts = {}) => {
    window.history[opts.replace ? 'replaceState' : 'pushState']({}, '', to)
    setFrom(opts.from ?? null)
    setPath(to)
  })

  if (checking) return <p>Checking session…</p>
  return (
    <NavCtx.Provider value={{ ...nav }}>
      <nav><button onClick={() => nav.go('/')}>Home</button> <button onClick={() => nav.go('/profile')}>Profile</button></nav>
      {path === '/login' ? <Login /> : path === '/profile' ? <ProtectedRoute><Profile /></ProtectedRoute> : <Home />}
    </NavCtx.Provider>
  )
}

export default function AuthApp({ api }) {
  return <AuthProvider api={api}><Pages /></AuthProvider>
}

