import { Component, useState } from 'react'

export default class ErrorBoundary extends Component {
  state = { error: null }

  static getDerivedStateFromError(error) {
    return { error }
  }

  componentDidCatch(error, info) {
    this.props.onError?.(error, info)
  }

  componentDidUpdate(prev) {
    const a = prev.resetKeys ?? []
    const b = this.props.resetKeys ?? []
    if (this.state.error && (a.length !== b.length || a.some((k, i) => !Object.is(k, b[i])))) this.reset()
  }

  reset = () => this.setState({ error: null })

  render() {
    const { error } = this.state
    if (!error) return this.props.children
    const { fallback } = this.props
    if (typeof fallback === 'function') return fallback({ error, reset: this.reset })
    if (fallback) return fallback
    return (
      <div role="alert">
        <p>Something went wrong</p>
        <pre>{error.message}</pre>
        <button onClick={this.reset}>Try again</button>
      </div>
    )
  }
}

// throw the error during the next render, where the boundary can catch it
export function useErrorHandler() {
  const [error, setError] = useState(null)
  if (error) throw error
  return setError
}

