import { useCallback, useEffect, useRef, useState } from 'react'

export function useDebouncedValue(value, delay) {
  const [v, setV] = useState(value)
  useEffect(() => {
    const id = setTimeout(() => setV(value), delay)
    return () => clearTimeout(id)
  }, [value, delay])
  return v
}

const read = (key, initial) => {
  try { const raw = localStorage.getItem(key); return raw === null ? initial : JSON.parse(raw) } catch { return initial }
}

export function useLocalStorage(key, initial) {
  const [value, setState] = useState(() => read(key, initial))
  const setValue = useCallback((next) => {
    setState((prev) => {
      const v = typeof next === 'function' ? next(prev) : next
      localStorage.setItem(key, JSON.stringify(v))
      return v
    })
  }, [key])
  useEffect(() => {
    const onStorage = (e) => { if (e.key === key) setState(e.newValue === null ? initial : JSON.parse(e.newValue)) }
    window.addEventListener('storage', onStorage)
    return () => window.removeEventListener('storage', onStorage)
  }, [key]) // eslint-disable-line react-hooks/exhaustive-deps
  return [value, setValue]
}

export function useClickOutside(ref, handler) {
  const saved = useRef(handler)
  useEffect(() => { saved.current = handler })
  useEffect(() => {
    const onDown = (e) => { if (ref.current && !ref.current.contains(e.target)) saved.current(e) }
    document.addEventListener('mousedown', onDown)
    return () => document.removeEventListener('mousedown', onDown)
  }, [ref])
}

export function useWindowSize() {
  const [size, setSize] = useState(() => ({ width: window.innerWidth, height: window.innerHeight }))
  useEffect(() => {
    const onResize = () => setSize({ width: window.innerWidth, height: window.innerHeight })
    window.addEventListener('resize', onResize)
    return () => window.removeEventListener('resize', onResize)
  }, [])
  return size
}

export function usePrevious(value) {
  const ref = useRef(undefined)
  useEffect(() => { ref.current = value }, [value])
  return ref.current
}

export function useIntersection(ref, options) {
  const [visible, setVisible] = useState(false)
  useEffect(() => {
    if (!ref.current) return
    const obs = new IntersectionObserver(([entry]) => setVisible(entry.isIntersecting), options)
    obs.observe(ref.current)
    return () => obs.disconnect()
  }, [ref]) // eslint-disable-line react-hooks/exhaustive-deps
  return visible
}
